module parity_8bit (
    input [7:0] in,
    output out
);
    reg [7:0] temp;
    reg result;

    always @(*) begin
        result = 1'b0;
        temp = in;
        for (integer i = 0; i < 8; i = i + 1) begin
            if (temp[0]) begin
                result = ~result;
            end
            temp = temp >> 1;
        end
    end

    assign out = result;
endmodule

