module majority (
    input a, b, c,
    output out
);
    wire [7:0] s;
    assign s[0] = a & b & c;
    assign s[1] = a & ~b & ~c;
    assign s[2] = ~a & b & ~c;
    assign s[3] = ~a & ~b & c;
    assign s[4] = a & b & ~c;
    assign s[5] = a & ~b & c;
    assign s[6] = ~a & b & c;
    assign s[7] = ~a & ~b & ~c;

    reg [2:0] pos;
    always @(*) begin
        pos = 3'd0;
        if (s[7])       pos = 3'd7;
        else if (s[6])  pos = 3'd6;
        else if (s[5])  pos = 3'd5;
        else if (s[4])  pos = 3'd4;
        else if (s[3])  pos = 3'd3;
        else if (s[2])  pos = 3'd2;
        else if (s[1])  pos = 3'd1;
        else if (s[0])  pos = 3'd0;
    end

    assign out = (pos < 3'd4) ? 1'b0 : 1'b1;
endmodule

module majority (
    input a, b, c,
    output out
);
    wire [7:0] s;
    assign s[0] = a & b & c;
    assign s[1] = a & b & ~c;
    assign s[2] = a & ~b & c;
    assign s[3] = a & ~b & ~c;
    assign s[4] = ~a & b & c;
    assign s[5] = ~a & b & ~c;
    assign s[6] = ~a & ~b & c;
    assign s[7] = ~a & ~b & ~c;

    reg [2:0] selector;
    always @(*) begin
        case ({b, c, a})
            3'b111: selector = 3'd0;
            3'b110: selector = 3'd1;
            3'b101: selector = 3'd2;
            3'b100: selector = 3'd3;
            3'b011: selector = 3'd4;
            3'b010: selector = 3'd5;
            3'b001: selector = 3'd6;
            3'b000: selector = 3'd7;
            default: selector = 3'd0;
        endcase
    end

    assign out = s[selector];
endmodule

module majority (
    input a, b, c,
    output out
);
    wire not_a, not_b, not_c;
    wire inter1, inter2, inter3, inter4, inter5;

    // Invert inputs
    not(not_a, a);
    not(not_b, b);
    not(not_c, c);

    // Intermediate terms (AND of inverted inputs)
    and(inter1, not_a, not_b, not_c);

    // Single-input NOR terms
    nor(inter2, a);
    nor(inter3, b);
    nor(inter4, c);

    // Combine NOR terms with OR
    or(inter5, inter2, inter3, inter4);

    // Finally, combine with AND
    and(out, inter1, inter5);
endmodule

