module majority (
    input a, b, c,
    output out
);
    wire [15:0] f;

    assign f[0] = a;
    assign f[1] = b;
    assign f[2] = c;

    genvar i;
    generate
        for (i = 3; i < 16; i = i + 1) begin : ring
            assign f[i] = (f[i-1] & ~f[i-2]) | (f[i-2] & ~f[i-3]);
        end
    endgenerate

    assign out = f[15];
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

wire [3:0] S;
wire [3:0] nq;

// Invert binary bits to get nq
assign nq = ~binary;

// Generate sum S using XNOR, XOR, NAND, and NOT gates
assign S[0] = binary[0] ~^ nq[0]; // XNOR
assign S[1] = (binary[1] ^ nq[1]) ~^ (binary[1] ^ nq[1]); // XOR implemented with NAND/XOR
assign S[2] = (binary[2] ~& nq[2]) | (nq[2] ~& binary[2]); // NAND and NOT combinations
assign S[3] = ~(binary[3] & nq[3]) & (~(binary[3] | nq[3])); // NAND and OR/NAND

// Assign output gray
assign gray = S;

endmodule

