module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

wire [3:0] f;

// Compute intermediate signal f using XOR, AND, NOT gates
assign f[0] = (binary[0] ^ binary[1]) & (~binary[2]);
assign f[1] = (binary[2] ^ binary[3]) & (~binary[1]);
assign f[2] = (binary[1] ^ binary[2]) & (~binary[3]);
assign f[3] = (binary[3] ^ binary[0]) & (~binary[2]);

// Determine output using logic gates
assign gray[0] = f[0];
assign gray[1] = f[1];
assign gray[2] = f[2] & f[3]; // AND gate for gray[2]
assign gray[3] = f[3];

endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

    wire [3:0] D;

    // Invert each bit of binary using AND gates (binary & ~binary)
    assign D[0] = binary[0] & ~binary[0];
    assign D[1] = binary[1] & ~binary[1];
    assign D[2] = binary[2] & ~binary[2];
    assign D[3] = binary[3] & ~binary[3];

    // Buffer each inverted bit using two AND gates
    assign gray[0] = D[0] & D[0];
    assign gray[1] = D[1] & D[1];
    assign gray[2] = D[2] & D[2];
    assign gray[3] = D[3] & D[3];

endmodule

