module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire [3:0] G, P;
    wire [4:0] C;

    assign C[0] = 1'b0;

    // Generate G and P terms for each bit
    assign G[0] = a[0] & b[0];
    assign P[0] = a[0] | b[0];

    // Carry computation for each bit
    assign C[1] = G[0] | (P[0] & C[0]);
    assign C[2] = G[1] | (P[1] & C[1]);
    assign C[3] = G[2] | (P[2] & C[2]);
    assign C[4] = G[3] | (P[3] & C[3]);

    assign equal = C[4];
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

wire [3:0] p;
wire [3:0] g;
wire [4:0] c;

// Generate and propagate signals
assign p = a | b;
assign g = a & b;

// Carry chain calculations
assign c[0] = g[0];
assign c[1] = g[1] | (p[1] & c[0]);
assign c[2] = g[2] | (p[2] & c[1]);
assign c[3] = g[3] | (p[3] & c[2]);
assign c[4] = g[0] | (p[0] & g[1]) | (p[0] & p[1] & g[2]) | (p[0] & p[1] & p[2] & g[3]);

assign equal = p[3] & p[2] & p[1] & p[0];

endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire [3:0] P, G;
    wire [3:0] carry;

    // Generate Propagate (P) and Generate (G) signals
    assign P = a | b;
    assign G = a & b;

    // Compute carry signals using look-ahead logic
    assign carry[0] = G[0];  // carry[0] is G0
    assign carry[1] = G[1] | (P[1] & G[0]);  // carry[1] is G1 or P1&G0
    assign carry[2] = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]);  // carry[2] is G2 or P2&G1 or P2&P1&G0
    assign carry[3] = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & G[0]);  // carry[3] is G3 or P3&G2 or P3&P2&G1 or P3&P2&P1&G0

    // equal is the final carry
    assign equal = carry[3];
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire [3:0] A_n, B_n;
    wire [3:0] and_out;
    wire [3:0] or_out;
    wire [3:0] n_or_out;
    wire [3:0] led_assign;

    // Generate inverted inputs using NAND gates
    nand(and_out[0], a[0], b[0]);
    nand(and_out[1], a[1], b[1]);
    nand(and_out[2], a[2], b[2]);
    nand(and_out[3], a[3], b[3]);

    // Generate inverted outputs using NAND gates
    nand(n_or_out[0], equal, equal);
    nand(n_or_out[1], equal, equal);
    nand(n_or_out[2], equal, equal);
    nand(n_or_out[3], equal, equal);

    // Perform AND operations for each bit
    nand(led_assign[0], and_out[0], n_or_out[0]);
    nand(led_assign[1], and_out[1], n_or_out[1]);
    nand(led_assign[2], and_out[2], n_or_out[2]);
    nand(led_assign[3], and_out[3], n_or_out[3]);

    // Combine using OR gates to drive LEDs
    or(equal, led_assign[0], led_assign[1], led_assign[2], led_assign[3]);

    // Assign LEDs to display the result
    assign a = equal;

endmodule

