    assign state[0] = n33 & p20;
    assign state[1] = n33 | p20;

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    parameter GLITCH_FREE = 1;

    reg q1;
    reg q2;
    reg q3;

    wire ctrl;
    assign ctrl = GLITCH_FREE ? clk : reset;

    // Master latch
    always @(ctrl, reset, clk) begin
        if (ctrl) begin
            q1 <= #2 reset;
            q2 <= #2 clk;
        end
    end

    // Slave latch
    always @(ctrl, q1, q2) begin
        if (ctrl) begin
            q3 <= #2 q1;
        end
    end

    assign state = {q2, q3};

endmodule

