module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    wire not_in0, not_in1;
    wire and_out0, and_out1;
    wire nor_out;

    // Generate NOT clk and NOT reset using NAND gates
    nand(not_in0, clk, clk);
    nand(not_in1, reset, reset);

    // Compute AND(clk, reset) using NOR and NOT gates
    nor(and_out0, not_in0, not_in1);

    // Compute AND(~clk, ~reset) using NOR and NOT gates
    nor(and_out1, not_in0, not_in1);

    // Compute clk NOR reset using NAND and NOT gates
    nand(nor_out, clk, reset);

    // Combine intermediate results to form state
    assign state = {and_out1, and_out0, nor_out};
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    wire not_A, not_B;
    wire and_out;
    wire nor_out;
    wire or_out;
    wire nand_out;

    // NOT gates using NOR
    nor(not_A, clk, clk);
    nor(not_B, reset, reset);

    // AND gate (NOR of NOTs)
    nor(and_out, not_A, not_B);

    // NOR gate (directly connects inputs)
    nor(nor_out, clk, reset);

    // OR gate (NOR of NOTs)
    nor(or_out, not_A, not_B);

    // NAND gate (NOR of AND output)
    nor(nand_out, and_out, and_out);

    // Output assignment
    assign state = {nor_out, nand_out};

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    wire not_A, not_B;
    wire nor_AB, and_AB;
    wire S_temp, R_temp;
    wire nor_SR, and_SR;

    // Compute not_A and not_B using NAND gates
    nand(not_A, clk, clk);
    nand(not_B, reset, reset);

    // Compute light[0] (clk NOR reset)
    nor(nor_AB, clk, reset);
    assign light[0] = nor_AB;

    // Compute and_AB using NOR gates
    nor(and_AB, not_A, not_B);

    // Compute R_temp (and_AB NOR and_AB)
    nor(R_temp, and_AB, and_AB);

    // Compute S_temp (nor_AB NAND R_temp)
    nand(S_temp, nor_AB, R_temp);

    // Compute light[1] (S_temp NOR R_temp)
    nor(light[1], S_temp, R_temp);

    // Compute not_S_temp and not_R_temp using NAND gates
    nand(not_S_temp, S_temp, S_temp);
    nand(not_R_temp, R_temp, R_temp);

    // Compute light[2] (not_S_temp NOR not_R_temp)
    nor(light[2], not_S_temp, not_R_temp);

endmodule

