module traffic_light (
    input clk, reset,
    output [2:0] light
);
    wire c;
    wire n1, n2, n3, n4, n5, n6, n7, n8, n9, n10, n11, n12, n13, n14, n15, n16, n17, n18, n19, n20, n21, n22, n23, n24, n25, n26, n27, n28, n29, n30, n31, n32;

    // Compute c = clk XOR reset using NAND gates
    assign n1 = ~(clk & reset);
    assign n2 = ~(clk & n1);
    assign n3 = ~(reset & n1);
    assign n4 = ~(n2 & n3);
    assign c = ~(n4 & n4);

    // Compute light[0] = (clk NAND reset) NAND (clk NAND clk)
    assign n5 = ~(clk & clk);
    assign n6 = ~(reset & reset);
    assign n7 = ~(n5 & n6);
    assign light[0] = ~(c & n7);

    // Compute light[1] = (clk NAND (clk NAND reset)) NAND (reset NAND (clk NAND reset))
    assign n8 = ~(clk & n4);
    assign n9 = ~(reset & n4);
    assign n10 = ~(n8 & n9);
    assign light[1] = ~(n10 & n10);

    // Compute light[2] = ((clk NAND reset) NAND (clk NAND clk)) NAND ((clk NAND (clk NAND reset)) NAND (reset NAND (clk NAND reset)))
    assign n11 = ~(n7 & n7);
    assign n12 = ~(n10 & n10);
    assign n13 = ~(n11 & n12);
    assign light[2] = ~(n13 & n13);

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // Generate all complemented input literals
    wire not_pi0, not_pi1, not_pi2;
    not(not_pi0, clk);
    not(not_pi1, reset);

    // Generate AND terms for each input literal
    wire and_pi0, and_pi1, and_pi2;
    and(and_pi0, clk, clk);        // Equivalent to clk
    and(and_pi1, reset, not_pi1);  // Equivalent to ~reset
    and(and_pi2, clk, reset);      // Intermediate term

    // Generate OR terms using drive capability gating
    or(light[0], and_pi0, and_pi1);  // light[0] = clk | ~reset
    or(light[1], and_pi1, and_pi2);  // light[1] = ~reset | clk* (assuming and_pi2 is clk&reset)
    or(light[2], and_pi0, and_pi2);  // light[2] = clk | clk* (assuming and_pi2 is clk&reset)

