    wire term1, term2;

    // Compute N1 = ~clk using NAND (clk NAND clk)
    nand(N1, clk, clk);

    // Compute N2 = reset NAND reset
    nand(N2, reset, reset);

    // Compute N3 = up_request NAND up_request
    nand(N3, up_request, up_request);

    // Compute N4 = down_request NAND down_request
    nand(N4, down_request, down_request);

    // Calculate term1 = (N1 NAND N3) using two NAND gates
    nand(term1, N1, N3);

    // Calculate term2 = (N2 NAND N4) using two NAND gates
    nand(term2, N2, N4);

    // Final output: NAND of term1 and term2
    nand(state, term1, term2);

