module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    // Implementation of 2-bit comparator using basic gates
    wire not_A1, not_A0;
    wire not_B1, not_B0;
    wire term1, term2, term3, term4;

    // Invert input bits
    not(not_A1, clk);
    not(not_A0, reset);
    not(not_B1, up_request);
    not(not_B0, down_request);

    // Generate AND terms for each case
    and(term1, not_A1, not_A0, not_B1, not_B0); // Case 0: both low
    and(term2, not_A1, reset,   not_B1, not_B0); // Case 1: A1 low, A0 high
    and(term3, clk,   not_A0, not_B1, down_request);   // Case 2: A1 high, A0 low
    and(term4, clk,   reset,    up_request,    down_request);    // Case 3: both high

    // Combine terms using OR gates
    or(state[1], term1, term2, term3, term4);

    // For state[0], need to track A0 and B0 differences
    wire not_A0_b, not_B0_a;
    not(not_A0_b, reset);
    not(not_B0_a, down_request);

    wire term2a, term3a, term4a;
    and(term2a, not_A1, reset,   not_B1, not_B0); // A0 high, B0 low
    and(term3a, clk,   not_A0, not_B1, down_request);   // A0 low, B0 high (corrected)
    and(term4a, clk,   reset,    up_request,    not_B0_a); // A1 high, A0 high, B1 high, B0 low

    or(state[0], term2a, term3a, term4a);
endmodule

module elevator_controller (
