    assign a_selec = (4'b0001 << clk);

    // 2-to-4 decoder for reset
    assign b_selec = (4'b0001 << reset);

    // AND plane: 4-bit vector of AND results
    wire [3:0] and_plane = a_selec & b_selec;

    // OR plane: 4-bit vector of OR results
    wire [3:0] or_plane = a_selec | b_selec;

    // 2-to-1 mux for state[1]
    assign state[1] = (and_plane[1] | and_plane[3]) ? 1'b1 :
                      (or_plane[1] | or_plane[3]) ? 1'b1 : 1'b0;

    // 2-to-1 mux for state[0]
    assign state[0] = (and_plane[0] | and_plane[2]) ? 1'b1 :
                      (or_plane[0] | or_plane[2]) ? 1'b1 : 1'b0;

endmodule

