    wire [7:0] left_rotated = {data_in[6:0], data_in[7]};

    // Perform right rotation on original if right_rot is non-zero
    wire [7:0] right_rotated = (right_rot != 2'd0) ? {data_in[data_in.length -1], data_in[7:1]} : data_in;

    // Choose output based on cases
    reg [7:0] y;
    always @(*) begin
        case (1'b1)
            KEY[0]: y = left_rotated;       // Case 1: KEY LSB is 1
            KEY[1]: y = right_rotated;      // Case 2: KEY second bit is 1
            KEY[2]: y = left_rotated;       // Case 3: KEY third bit is 1
            KEY[3]: y = right_rotated;      // Case 4: KEY fourth bit is 1
            default: y = data_in;            // Default to original
        endcase
    end

