        if (en_sync && !sel0_sync && !sel1_sync) begin
            if (in[0] == 0) begin // Pressed (active low)
                hold_counter[0] <= 0;
                state[0] <= 0;
            end else begin
                if (hold_counter[0] < DEBOUNCE_CYCLES)
                    hold_counter[0] <= hold_counter[0] + 1;
                if (hold_counter[0] == DEBOUNCE_CYCLES) begin
                    state[0] <= 1;
                    hold_counter[0] <= 0;
