            state_counter <= 2'd0;
        end else begin
            if (load && !rst) begin
                index_reg <= next_index;
                state_counter <= state_counter + 1;
            end
        end
    end

    // Open lock when last state is reached
    assign sout = (state_counter == 2'd3);

