    _unused_sw = 1'b0;
  end

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  reg [2:0] q_reg;

  always @(posedge clk) begin
    if (resetn)
      q_reg <= r;
    else
      q_reg <= {q_reg[1], q_reg[0], 1'b0};
  end

  assign g = q_reg;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  wire [2:0] A_delayed, B_delayed;
  wire [2:0] control_delayed;

  // Invert input clocks
  assign A_delayed = ~r;
  assign B_delayed = ~r;

  // Delay control signal by 2 time units
  assign control_delayed = #2 clk;

  // Generate gated clocks
  assign g[0] = A_delayed[0] & control_delayed[0];
  assign g[1] = B_delayed[1] & control_delayed[1];
  assign g[2] = A_delayed[2] & control_delayed[2];

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  reg [2:0] q1, q2;

  // Flip-flop q1: updates on positive clock edge
  always @(posedge clk) begin
    if (resetn)
      q1 <= r;
    else
      q1 <= 3'b0;  // Reset to 0 when resetn is inactive
  end

  // Flip-flop q2: updates on negative clock edge
  always @(negedge clk) begin
    if (resetn)
      q2 <= r;
    else
      q2 <= 3'b0;  // Reset to 0 when resetn is inactive
  end

  // Output combines current q1 and q2
  assign g = {q1, q2};

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);
  reg [2:0] Q [0:2];  // Q[0] is flip-flop A, Q[1] and Q[2] are parts of flip-flop B

  // Tile 0: Flip-flop A (D input TopModule)
  always @(posedge clk or posedge resetn) begin
    if (resetn)
      Q[0] <= 1'b0;
    else
      Q[0] <= r[0];  // D input from r[0]
  end

  // Tile 1: Inverter controlling flip-flop B's D input
  wire D_B = ~Q[0];  // Invert Q[0] for flip-flop B's D input

  // Tile 2: Flip-flop B (D input TopModule)
  always @(posedge clk or posedge resetn) begin
    if (resetn)
      Q[1] <= 1'b0;
    else
      Q[1] <= D_B;  // D input from inverter output
  end

  // Tile 3: Two-incrementer chain (r[1] and r[2] as feedback)
  always @(posedge clk or posedge resetn) begin
    if (resetn) begin
      Q[2] <= 1'b0;
      Q[1] <= 1'b0;
    end else begin
      Q[2] <= Q[1];  // Shift left
      Q[1] <= Q[2] ^ r[1];  // XOR with r[1] as incrementer feedback
    end
  end

  assign g = {Q[2], Q[1], Q[0]};  // Output state of flip-flops
endmodule

