  always @(posedge clk) begin
    if (w) begin
      stage <= 3'b000;
      Q <= 1'b0;
    end else begin
      // Update stage register
      if (R)
        stage <= {stage[1:0], L};
      else
        stage <= {stage[1:0], 1'b0};

      // Update output register
      if (E)
        Q <= w ? 1'b0 : stage[2];
    end
  end

endmodule

