  output out_assign,
  output reg out_alwaysblock
);
  reg busy;
  reg [31:0] shift_reg;
  reg [4:0] counter;

  assign out_assign = ~busy;

  always @(*) begin
    if (b && !busy)
      out_alwaysblock = 1'b1;
    else
      out_alwaysblock = 1'b0;
  end

  always @(posedge a) begin
    if (b && !busy) begin
      busy <= 1'b1;
      counter <= 5'd0;
      shift_reg <= 32'd0;
      out_alwaysblock <= 1'b1;
    end
    else if (busy) begin
      if (counter < 5'd16) begin
        shift_reg <= {shift_reg[30:0], a};
        counter <= counter + 5'd1;
        out_alwaysblock <= 1'b0;
      end
      else begin
        busy <= 1'b0;
        out_alwaysblock <= 1'b1;
      end
    end
  end
