module TopModule (
  input a,
  input b,
  output out_assign,
  output reg out_alwaysblock
);

  parameter COUNTER_MAX = 125000; // Adjust based on clock frequency (e.g., 125000 for 100MHz to achieve 1.25ms per state)

  reg [2:0] state, next_state;
  reg [19:0] counter;

  // State definitions
  localparam Q0 = 3'b000,
             Q1 = 3'b001,
             Q2 = 3'b010,
             Q3 = 3'b011,
             Q4 = 3'b100,
             Q5 = 3'b101,
             Q6 = 3'b110,
             Q7 = 3'b111;

  // State transition and counter logic
  always @(posedge a) begin
    if (b) begin
      state <= Q0;
      counter <= 0;
      out_alwaysblock <= 0;
    end else begin
      state <= next_state;
      if (counter == COUNTER_MAX)
        counter <= 0;
      else
        counter <= counter + 1;
    end
  end

  // Next state logic
  always @(*) begin
    case (state)
      Q0: next_state = (counter == COUNTER_MAX) ? Q1 : Q0;
      Q1: next_state = (counter == COUNTER_MAX) ? Q2 : Q1;
      Q2: next_state = (counter == COUNTER_MAX) ? Q3 : Q2;
      Q3: next_state = (counter == COUNTER_MAX) ? Q4 : Q3;
      Q4: next_state = (counter == COUNTER_MAX) ? Q5 : Q4;
      Q5: next_state = (counter == COUNTER_MAX) ? Q6 : Q5;
      Q6: next_state = (counter == COUNTER_MAX) ? Q7 : Q6;
      Q7: next_state = (counter == COUNTER_MAX) ? Q0 : Q7;
      default: next_state = Q0;
    endcase
  end

  // out_alwaysblock control signal
  always @(*) begin
    out_alwaysblock = (state == Q4) ? 1'b1 : 1'b0;
  end

  // out_assign is always 1
  assign out_assign = 1'b1;

endmodule

module TopModule (
