      16'b0111xxxx: {left, down, right, up} = 4'b0100;
      16'b0100xxxx: {left, down, right, up} = 4'b0101;
      16'b0011xxxx: {left, down, right, up} = 4'b0110;
      16'b0000xxxx: {left, down, right, up} = 4'b0111;
