module TopModule (
  input [15:0] scancode,
  output reg left,
  output reg down,
  output reg right,
  output reg up
);

  // Define states
  localparam [3:0]
    IDLE = 4'd0,
    CONV1 = 4'd1,
    CONV2 = 4'd2,
    CONV3 = 4'd3,
    CONV4 = 4'd4,
    CONV5 = 4'd5,
    CONV6 = 4'd6,
    FINISH = 4'd7;

  reg [3:0] current_state, next_state;
  reg [15:0] acc;

  // State transition and acc logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      current_state <= IDLE;
      acc <= 16'd0;
    end else begin
      current_state <= next_state;
      case (current_state)
        CONV1: acc <= acc + scancode;
        CONV2: acc <= acc - scancode;
        CONV3: acc <= acc + scancode;
        CONV4: acc <= acc - scancode;
        CONV5: acc <= acc + scancode;
        CONV6: acc <= acc - scancode;
        default: acc <= acc;
      endcase
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE: next_state = CONV1;
      CONV1: next_state = CONV2;
      CONV2: next_state = CONV3;
      CONV3: next_state = CONV4;
      CONV4: next_state = CONV5;
      CONV5: next_state = CONV6;
      CONV6: next_state = FINISH;
      FINISH: next_state = FINISH;
      default: next_state = IDLE;
    endcase
  end

  // Output logic
  always @(*) begin
    left = (current_state == CONV1 || current_state == CONV3 || current_state == CONV5);
    down = (current_state == CONV2 || current_state == CONV4 || current_state == CONV6);
    right = (current_state == FINISH);
    up = (current_state != IDLE);
  end

endmodule

module TopModule (
