module TopModule (
  input a,
  input b,
  output q
);
  wire [15:0] cat [255:0];
  wire [255:0] f;

  // Generate intermediate signals 'cat' with random values during simulation
  generate
    genvar i;
    for (i = 0; i < 256; i = i + 1) begin : cat_gen
      assign cat[i] = {i[15:0], $random[15:0]};
    end
  endgenerate

  // Compute 'f' by XORing adjacent 'cat' values according to the specified pattern
  assign f[0]  = cat[0]  ^ cat[1];
  assign f[1]  = cat[1]  ^ cat[2];
  assign f[2]  = cat[3]  ^ cat[4];
  assign f[3]  = cat[2]  ^ cat[5];
  assign f[4]  = cat[7]  ^ cat[8];
  assign f[5]  = cat[6]  ^ cat[9];
  assign f[6]  = cat[7]  ^ cat[10];
  assign f[7]  = cat[8]  ^ cat[11];
  assign f[8]  = cat[9]  ^ cat[12];
  assign f[9]  = cat[10] ^ cat[13];
  assign f[10] = cat[11] ^ cat[14];
  assign f[11] = cat[12] ^ cat[15];
  assign f[12] = cat[13] ^ cat[16];
  assign f[13] = cat[14] ^ cat[17];
  assign f[14] = cat[15] ^ cat[18];
  assign f[15] = cat[16] ^ cat[19];
  assign f[16] = cat[17] ^ cat[20];
  assign f[17] = cat[18] ^ cat[21];
  assign f[18] = cat[19] ^ cat[22];
  assign f[19] = cat[20] ^ cat[23];
  assign f[20] = cat[21] ^ cat[24];
  assign f[21] = cat[22] ^ cat[25];
  assign f[22] = cat[23] ^ cat[25];
  assign f[23] = cat[24] ^ cat[25];
  assign f[24] = cat[25] ^ cat[0];
  assign f[25] = cat[0]  ^ cat[1];

  // Select the index of the most significant '1' in the feedback chain
  reg [4:0] msb_pos;
  always @(*) begin
    msb_pos = 5'd0;
    if (f[25])       msb_pos = 5'd25;
    else if (f[24])  msb_pos = 5'd24;
    else if (f[23])  msb_pos = 5'd23;
    else if (f[22])  msb_pos = 5'd22;
    else if (f[21])  msb_pos = 5'd21;
    else if (f[20])  msb_pos = 5'd20;
    else if (f[19])  msb_pos = 5'd19;
    else if (f[18])  msb_pos = 5'd18;
    else if (f[17])  msb_pos = 5'd17;
    else if (f[16])  msb_pos = 5'd16;
    else if (f[15])  msb_pos = 5'd15;
    else if (f[14])  msb_pos = 5'd14;
    else if (f[13])  msb_pos = 5'd13;
    else if (f[12])  msb_pos = 5'd12;
    else if (f[11])  msb_pos = 5'd11;
    else if (f[10])  msb_pos = 5'd10;
    else if (f[9])   msb_pos = 5'd9;
    else if (f[8])   msb_pos = 5'd8;
    else if (f[7])   msb_pos = 5'd7;
    else if (f[6])   msb_pos = 5'd6;
    else if (f[5])   msb_pos = 5'd5;
    else if (f[4])   msb_pos = 5'd4;
    else if (f[3])   msb_pos = 5'd3;
    else if (f[2])   msb_pos = 5'd2;
    else if (f[1])   msb_pos = 5'd1;
    else if (f[0])   msb_pos = 5'd0;
  end

  // Compute output by XORing cat[msb_pos] with its next neighbor
  assign q = cat[msb_pos] ^ cat[msb_pos + 1];
endmodule

module TopModule (
  input a,
  input b,
  output q
);

  wire [31:0] shift_reg;

  // Initialize shift register with all 1's (active-high reset creates this state)
  assign shift_reg = 32'hFFFFFFFF;

  // Shift left on each clock edge, capturing 0's as 1's and 1's as 0's
  always @(posedge a) begin
    shift_reg <= {shift_reg[30:0], ~b};
  end

  // Output the MSB of the shift register
  assign q = shift_reg[31];

endmodule

module TopModule (
  input [2:0] a,
  output reg [15:0] q
);

  // Define 8 distinct 16-bit values for addresses 0x00 to 0x07
  localparam [15:0] ADDR0 = 16'h0000;
  localparam [15:0] ADDR1 = 16'h1111;
  localparam [15:0] ADDR2 = 16'h2222;
  localparam [15:0] ADDR3 = 16'h3333;
  localparam [15:0] ADDR4 = 16'h4444;
  localparam [15:0] ADDR5 = 16'h5555;
  localparam [15:0] ADDR6 = 16'h6666;
  localparam [15:0] ADDR7 = 16'h7777;

  always @(*) begin
    case (a)
      3'b000: q = ADDR0;
      3'b001: q = ADDR1;
      3'b010: q = ADDR2;
      3'b011: q = ADDR3;
      3'b100: q = ADDR4;
      3'b101: q = ADDR5;
      3'b110: q = ADDR6;
      3'b111: q = ADDR7;
      default: q = 16'bx; // Handles undefined cases (if any)
    endcase
  end

endmodule

module TopModule (
  input clk,
  input a,
  output reg q
);

  localparam IDLE = 1'b0;
  localparam PULSE = 1'b1;
  localparam WAIT = 1'b2;

  reg [1:0] state;
  reg counter;

  always @(posedge clk or negedge a) begin
    if (!a) begin
      state <= IDLE;
      counter <= 0;
      q <= 0;
    end else begin
      case (state)
        IDLE: begin
          q <= 0;
          if (q == 0 && a == 1) begin
            state <= PULSE;
            counter <= 0;
          end
        end
        PULSE: begin
          q <= 1;
          counter <= 0;
          state <= WAIT;
        end
        WAIT: begin
          q <= 0;
          if (counter == 1) begin
            state <= IDLE;
          end else begin
            counter <= counter + 1;
            state <= WAIT;
          end
        end
        default: state <= IDLE;
      endcase
    end
  end

endmodule

`timescale 1ns / 100ps

module TopModule (
  input clk,
  input a,
  output reg q
);

  parameter DEPTH = 32;
  localparam SHIFT = 1;

  reg [DEPTH-1:0] shift_reg;

  always @(posedge clk) begin
    if (a) begin
      shift_reg <= {DEPTH{1'b0}};
      q <= 1'b0;
    end else begin
      reg [DEPTH-1:0] new_shift_reg;
      new_shift_reg = {shift_reg[DEPTH-2:0], 1'b0};
      new_shift_reg = new_shift_reg >> SHIFT;
      q <= new_shift_reg[DEPTH-1];
      shift_reg <= new_shift_reg;
    end
  end

endmodule

module TopModule (
  input clk,
  input a,
  output reg q
);

  reg [31:0] pc;
  reg [31:0] instr;
  reg [31:0] reg_file [0:31];
  reg [31:0] data_mem [0:1023];
  reg halt;

  // Pipeline registers
  reg [31:0] IF_ID_instr;
  reg [31:0] IF_ID_pc;
  reg [31:0] ID_EX_pc;
  reg [31:0] ID_EX_read1, ID_EX_read2;
  reg [31:0] ID_EX_imm;
  reg [31:0] ID_EX_op;
  reg [4:0] ID_EX_rs, ID_EX_rt, ID_EX_rd;
  reg ID_EX_reg_write, ID_EX_mem_write, ID_EX_mem_read, ID_EX_branch, ID_EX_halt;
  reg [31:0] ID_EX_data2;

  reg [31:0] EX_MEM_alu;
  reg [31:0] EX_MEM_write_data;
  reg [4:0] EX_MEM_rd;
  reg EX_MEM_reg_write, EX_MEM_mem_write, EX_MEM_mem_read;

  reg [31:0] MEM_WB_alu;
  reg [31:0] MEM_WB_data;
  reg [4:0] MEM_WB_rd;
  reg MEM_WB_reg_write;

  // Halt detection
  always @(posedge clk) begin
    if (!a) halt <= 0;
    else halt <= ID_EX_halt & EX_MEM_reg_write & MEM_WB_reg_write;
  end

  // IF Stage
  always @(posedge clk) begin
    if (!a || halt) begin
      IF_ID_instr <= 0;
      IF_ID_pc <= 0;
    end else if (!halt) begin
      IF_ID_instr <= instr[pc];
      IF_ID_pc <= pc;
      pc <= pc + 4;
    end
  end

  // ID Stage
  always @(posedge clk) begin
    if (!a || halt) begin
      ID_EX_pc <= 0;
      ID_EX_read1 <= 0;
      ID_EX_read2 <= 0;
      ID_EX_imm <= 0;
      ID_EX_op <= 0;
      ID_EX_rs <= 0;
      ID_EX_rt <= 0;
      ID_EX_rd <= 0;
      {ID_EX_reg_write, ID_EX_mem_write, ID_EX_mem_read, ID_EX_branch, ID_EX_halt} <= 0;
      ID_EX_data2 <= 0;
    end else begin
      ID_EX_pc <= IF_ID_pc;
      ID_EX_read1 <= reg_file[IF_ID_instr[25:21]]; // rs
      ID_EX_read2 <= reg_file[IF_ID_instr[20:16]]; // rt
      ID_EX_imm <= {{16{IF_ID_instr[15]}}, IF_ID_instr[15:0]};
      ID_EX_op <= IF_ID_instr[31:26];
      ID_EX_rs <= IF_ID_instr[25:21];
      ID_EX_rt <= IF_ID_instr[20:16];
      ID_EX_rd <= IF_ID_instr[15:11];
      ID_EX_reg_write <= (IF_ID_instr[20:16] != 0);
      ID_EX_mem_write <= IF_ID_instr[20:16];
      ID_EX_mem_read <= IF_ID_instr[15:11];
      ID_EX_branch <= (IF_ID_instr[31:26] == 6'h04 || IF_ID_instr[31:26] == 6'h05);
      ID_EX_halt <= IF_ID_instr[31:26] == 6'h00;
      ID_EX_data2 <= data_mem[IF_ID_instr[20:16]];
    end
  end

  // EX Stage
  always @(posedge clk) begin
    if (!a || halt) begin
      EX_MEM_alu <= 0;
      EX_MEM_write_data <= 0;
      EX_MEM_rd <= 0;
      {EX_MEM_reg_write, EX_MEM_mem_write, EX_MEM_mem_read} <= 0;
    end else begin
      case (ID_EX_op)
        6'b000000: begin // R-type
          EX_MEM_reg_write <= 1;
          EX_MEM_mem_write <= 0;
          EX_MEM_mem_read <= 0;
          EX_MEM_branch <= 0;
          case (ID_EX_rd)
            5'b00000: EX_MEM_alu <= ID_EX_read1; // sll
            5'b00001: EX_MEM_alu <= ID_EX_read2; // add
            5'b00010: EX_MEM_alu <= ID_EX_read2; // sub
            5'b00011: EX_MEM_alu <= ID_EX_read2; // and
            default: EX_MEM_alu <= 0;
          endcase
          EX_MEM_rd <= ID_EX_rd;
        end
        6'b000001: begin // I-type
          EX_MEM_reg_write <= 1;
          EX_MEM_mem_write <= 0;
          EX_MEM_mem_read <= 0;
          EX_MEM_branch <= 0;
          case (ID_EX_rd)
            5'b00000: EX_MEM_alu <= ID_EX_imm; // sll
            5'b00001: EX_MEM_alu <= ID_EX_imm; // addi
            5'b00010: EX_MEM_alu <= ID_EX_imm; // subi
            5'b00011: EX_MEM_alu <= ID_EX_imm; // andi
            default: EX_MEM_alu <= 0;
          endcase
          EX_MEM_rd <= ID_EX_rd;
        end
        6'b000010: begin // Load
          EX_MEM_reg_write <= 1;
          EX_MEM_mem_write <= 0;
          EX_MEM_mem_read <= 1;
          EX_MEM_branch <= 0;
          EX_MEM_alu <= ID_EX_imm;
          EX_MEM_rd <= ID_EX_rt;
        end
        6'b000011: begin // Store
          EX_MEM_reg_write <= 0;
          EX_MEM_mem_write <= 1;
          EX_MEM_mem_read <= 0;
          EX_MEM_branch <= 0;
          EX_MEM_alu <= ID_EX_imm;
        end
        6'b000100: begin // Branch
          EX_MEM_reg_write <= 0;
          EX_MEM_mem_write <= 0;
          EX_MEM_mem_read <= 0;
          EX_MEM_branch <= 1;
          EX_MEM_alu <= ID_EX_imm;
        end
        default: ;
      endcase
    end
  end

  // MEM Stage
  always @(posedge clk) begin
    if (!a || halt) begin
      MEM_WB_alu <= 0;
      MEM_WB_data <= 0;
      MEM_WB_rd <= 0;
      MEM_WB_reg_write <= 0;
    end else begin
      case (EX_MEM_op)
        6'b000000: begin // R-type
          MEM_WB_reg_write <= 1;
          MEM_WB_data <= EX_MEM_alu;
          MEM_WB_rd <= EX_MEM_rd;
        end
        6'b000001: begin // I-type
          MEM_WB_reg_write <= 1;
          MEM_WB_data <= EX_MEM_alu;
          MEM_WB_rd <= EX_MEM_rd;
        end
        6'b000010: begin // Load
          MEM_WB_reg_write <= 1;
          MEM_WB_data <= data_mem[EX_MEM_alu[20:16]];
          MEM_WB_rd <= EX_MEM_rd;
        end
        default: ;
      endcase
    end
  end

  // WB Stage
  always @(posedge clk) begin
    if (!a || halt) begin
      q <= 0;
    end else begin
      if (MEM_WB_reg_write) q <= MEM_WB_data[20];
    end
  end

endmodule

module TopModule (
  input clk,
  input a,
  output reg q
);

  reg [1:0] state;

  localparam WAIT_ON_REQUEST = 2'b00,
             HANDLE_GATED_CLK = 2'b01,
             WAIT_ON_CLK = 2'b10;

  always @(posedge clk) begin
    if (a) begin
      state <= WAIT_ON_REQUEST;
      q <= 0;
    end else begin
      case (state)
        WAIT_ON_REQUEST: begin
          q <= 0;
          if (~q)
            state <= HANDLE_GATED_CLK;
        end
        HANDLE_GATED_CLK: begin
          state <= WAIT_ON_CLK;
          q <= q; // Retain output during handled cycle
        end
        WAIT_ON_CLK: begin
          q <= 0;
          if (q)
            state <= HANDLE_GATED_CLK;
        end
        default: begin
          state <= WAIT_ON_REQUEST;
          q <= 0;
        end
      endcase
    end
  end

endmodule

module TopModule (
  input clk,
  input a,
  output reg q
);

  reg [2:0] state, next_state;
  reg [2:0] dur_counter, next_dur_counter;

  parameter S0 = 3'd0,
            S1 = 3'd1,
            S2 = 3'd2,
            S3 = 3'd3,
            S4 = 3'd4;

  parameter DUR0 = 3'd0,
            DUR1 = 3'd1,
            DUR2 = 3'd2,
            DUR3 = 3'd3,
            DUR4 = 3'd4;

  always @(posedge clk or negedge a) begin
    if (!a) begin
      state <= S0;
      dur_counter <= DUR0;
      q <= 1'b0;
    end else begin
      state <= next_state;
      dur_counter <= next_dur_counter;
      q <= (next_state == S4);
    end
  end

  always @(*) begin
    next_state = state;
    next_dur_counter = dur_counter;
    if (state == S4) begin
      next_state = S0;
    end else if (dur_counter == DUR0) begin
      case (state)
        S0: next_state = S1;
        S1: next_state = S2;
        S2: next_state = S3;
        S3: next_state = S4;
        default: next_state = S0;
      endcase
      next_dur_counter = DUR1;
    end else begin
      next_dur_counter = dur_counter + 1;
    end
  end

endmodule

module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  wire [3:0] S;
  wire [3:0] S_next;

  assign S = q;

  assign S_next[3] = S[2] ^ S[1];
  assign S_next[2] = S[1] ^ S[0];
  assign S_next[1] = S[0];
  assign S_next[0] = 1'b0;

  always @(posedge clk) begin
    if (reset)
      q <= 4'b0000;
    else
      q <= S_next;
  end

endmodule

