module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  // State definitions
  localparam S0 = 4'b0000,
             S1 = 4'b0001,
             S2 = 4'b0010,
             S3 = 4'b0011,
             S4 = 4'b0100,
             S5 = 4'b0101,
             S6 = 4'b0110,
             S7 = 4'b0111,
             S8 = 4'b1000,
             S9 = 4'b1001,
             S10 =4'b1010;

  reg [3:0] current_state, next_state;

  // State transition logic
  always @(*) begin
    case (current_state)
      S0: next_state = clk ? S1 : S0;
      S1: next_state = clk ? S2 : S0;
      S2: next_state = clk ? S3 : S0;
      S3: next_state = clk ? S4 : S0;
      S4: next_state = clk ? S5 : S0;
      S5: next_state = clk ? S6 : S0;
      S6: next_state = clk ? S7 : S0;
      S7: next_state = clk ? S8 : S0;
      S8: next_state = clk ? S9 : S0;
      S9: next_state = clk ? S10 : S0;
      S10: next_state = clk ? S0 : S0;
      default: next_state = S0;
    endcase
  end

  // State register with synchronous reset
  always @(posedge reset) begin
    if (!reset)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  // Output assignment
  always @(*) begin
    q = current_state;
  end

endmodule

module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  reg [1:0] state;

  localparam IDLE = 2'b00;
  localparam S1 = 2'b01;
  localparam S2 = 2'b10;
  localparam S3 = 2'b11;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= IDLE;
      q <= 4'b0000;
    end else begin
      case (state)
        IDLE: begin
          state <= S1;
          q <= 4'b0000;
        end
        S1: begin
          state <= S2;
          q <= 4'b0001;
        end
        S2: begin
          state <= S3;
          q <= 4'b0010;
        end
        S3: begin
          state <= IDLE;
          q <= 4'b0010;
        end
        default: begin
          state <= IDLE;
          q <= 4'b0000;
        end
      endcase
    end
  end

endmodule

