module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  wire [3:0] S = {clk, q[3:1]};
  wire [3:0] G;

  assign G[0] = reset;
  assign G[1] = S[0] | (S[1] & G[0]);
  assign G[2] = S[0] | (S[1] & S[2] & G[0]);
  assign G[3] = S[0] | (S[1] & S[2] & S[3] & G[0]);

  reg [3:0] Y;
  assign Y[0] = G[0];
  assign Y[1] = G[1];
  assign Y[2] = G[2];
  assign Y[3] = G[3];

  reg [3:0] N;
  assign N = ~Y;

  reg [3:0] Q_next;
  assign Q_next[0] = N[0];
  assign Q_next[1] = (S[1] & N[0]) | (S[2] & N[1] & N[0]);
  assign Q_next[2] = (S[2] & S[1] & N[0]) | (S[3] & S[2] & N[1] & N[0]);
  assign Q_next[3] = (S[3] & S[2] & S[1] & N[0]) | (S[3] & S[2] & S[1] & S[0] & N[0]);

  always @(posedge clk) begin
    q <= Q_next;
  end

endmodule

