);

  wire [3:0] S = {clk, q[3:1]};
  wire [3:0] G = {q[3], q[2], q[1], q[0]};

  always @(*) begin
    if (reset) begin
      casex(S)
        4'b1??? : q = 4'b1111;
        4'b01?? : q = 4'b1110;
        4'b001? : q = 4'b1101;
        4'b0001 : q = 4'b1100;
        4'b101? : q = 4'b1011;
        4'b1001 : q = 4'b1010;
        4'b0101 : q = 4'b1001;
        4'b0010 : q = 4'b1000;
        4'b1010 : q = 4'b0111;
        4'b0100 : q = 4'b0110;
        4'b0000 : q = 4'b0101;
        default : q = 4'b0000;
      endcase
    end else begin
      q = 4'bxxxx;
    end
  end

  always @(*) begin
    if (reset) begin
      q[3] = G[3];
      q[2] = G[2];
      q[1] = G[1];
      q[0] = G[0];
    end
  end

