module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  parameter [1:0] RST       = 2'b00,
                  NO_OP     = 2'b01,
                  WRITE     = 2'b10,
                  READ_ONLY = 2'b11;

  reg [1:0] current_state, next_state;

  // State transition logic
  always @(*) begin
    case (current_state)
      RST: begin
        next_state = train_taken ? RST : (train_valid ? WRITE : READ_ONLY);
      end
      NO_OP: begin
        next_state = train_taken ? RST : (train_valid ? WRITE : READ_ONLY);
      end
      WRITE: begin
        next_state = train_taken ? RST : WRITE;
      end
      READ_ONLY: begin
        next_state = train_taken ? RST : READ_ONLY;
      end
      default: next_state = RST; // Handle undefined states
    endcase
  end

  // State register
  always @(posedge clk) begin
    if (areset)
      current_state <= RST;
    else
      current_state <= next_state;
  end

  assign state = current_state;

endmodule

module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

localparam [1:0] NO_MOTION_STILL = 2'b00;
localparam [1:0] NO_MOTION_LEFT  = 2'b01;
localparam [1:0] NO_MOTION_RIGHT = 2'b10;
localparam [1:0] NO_MOTION_DOWN  = 2'b11;

reg [1:0] state;

always @(posedge clk) begin
  if (areset) begin
    state <= NO_MOTION_STILL;
  end else begin
    case (state)
      NO_MOTION_STILL: begin
        if (train_taken) begin
          if (!train_valid)
            state <= NO_MOTION_STILL;
          else if (!clk)
            state <= NO_MOTION_STILL;
          else if (!train_valid && !clk)
            state <= NO_MOTION_STILL;
          else
            state <= NO_MOTION_STILL;
        end else if (train_valid) begin
          if (!train_taken)
            state <= NO_MOTION_STILL;
          else if (!clk)
            state <= NO_MOTION_STILL;
          else if (!train_taken && !clk)
            state <= NO_MOTION_STILL;
          else
            state <= NO_MOTION_STILL;
        end else begin
          if (train_taken && !train_valid && !clk)
            state <= NO_MOTION_STILL;
          else if (train_taken && !clk)
            state <= NO_MOTION_RIGHT;
          else if (train_taken && train_valid)
            state <= NO_MOTION_DOWN;
          else if (!train_taken && clk)
            state <= NO_MOTION_LEFT;
          else
            state <= NO_MOTION_STILL;
        end
      end

      NO_MOTION_LEFT: begin
        if (train_taken) begin
          if (!train_valid)
            state <= NO_MOTION_STILL;
          else if (!clk)
            state <= NO_MOTION_LEFT;
          else if (!train_valid && !clk)
            state <= NO_MOTION_LEFT;
          else
            state <= NO_MOTION_LEFT;
        end else if (train_valid) begin
          if (!train_taken)
            state <= NO_MOTION_STILL;
          else if (!clk)
            state <= NO_MOTION_LEFT;
          else if (!train_taken && !clk)
            state <= NO_MOTION_LEFT;
          else
            state <= NO_MOTION_LEFT;
        end else begin
          if (train_taken && !train_valid && !clk)
            state <= NO_MOTION_STILL;
          else if (train_taken && !clk)
            state <= NO_MOTION_RIGHT;
          else if (train_taken && train_valid)
            state <= NO_MOTION_DOWN;
          else if (!train_taken && clk)
            state <= NO_MOTION_LEFT;
          else
            state <= NO_MOTION_LEFT;
        end
      end

      NO_MOTION_RIGHT: begin
        if (train_taken) begin
          if (!train_valid)
            state <= NO_MOTION_STILL;
          else if (!clk)
            state <= NO_MOTION_RIGHT;
          else if (!train_valid && !clk)
            state <= NO_MOTION_RIGHT;
          else
            state <= NO_MOTION_RIGHT;
        end else if (train_valid) begin
          if (!train_taken)
            state <= NO_MOTION_STILL;
          else if (!clk)
            state <= NO_MOTION_RIGHT;
          else if (!train_taken && !clk)
            state <= NO_MOTION_RIGHT;
          else
            state <= NO_MOTION_RIGHT;
        end else begin
          if (train_taken && !train_valid && !clk)
            state <= NO_MOTION_STILL;
          else if (train_taken && !clk)
            state <= NO_MOTION_LEFT;
          else if (train_taken && train_valid)
            state <= NO_MOTION_DOWN;
          else if (!train_taken && clk)
            state <= NO_MOTION_RIGHT;
          else
            state <= NO_MOTION_RIGHT;
        end
      end

      NO_MOTION_DOWN: begin
        if (train_taken) begin
          if (!train_valid)
            state <= NO_MOTION_STILL;
          else if (!clk)
            state <= NO_MOTION_DOWN;
          else if (!train_valid && !clk)
            state <= NO_MOTION_DOWN;
          else
            state <= NO_MOTION_DOWN;
        end else if (train_valid) begin
          if (!train_taken)
            state <= NO_MOTION_STILL;
          else if (!clk)
            state <= NO_MOTION_DOWN;
          else if (!train_taken && !clk)
            state <= NO_MOTION_DOWN;
          else
            state <= NO_MOTION_DOWN;
        end else begin
          if (train_taken && !train_valid && !clk)
            state <= NO_MOTION_STILL;
          else if (train_taken && !clk)
            state <= NO_MOTION_RIGHT;
          else if (train_taken && train_valid)
            state <= NO_MOTION_LEFT;
          else if (!train_taken && clk)
            state <= NO_MOTION_DOWN;
          else
            state <= NO_MOTION_DOWN;
        end
      end

      default: state <= NO_MOTION_STILL;
    endcase
  end
end

assign state = state;

endmodule

module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  // State definitions
  localparam [1:0] NS_GREEN  = 2'b00,
                   NS_YELLOW = 2'b01,
                   EW_GREEN  = 2'b10,
                   EW_YELLOW = 2'b11;

  reg [1:0] current_state, next_state;

  // State register with synchronous areset
  always @(posedge clk) begin
    if (areset)
      current_state <= NS_GREEN;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      NS_GREEN:   next_state = train_taken ? NS_YELLOW : NS_GREEN;
      NS_YELLOW:  next_state = train_taken ? EW_GREEN : NS_YELLOW;
      EW_GREEN:   next_state = train_valid ? EW_YELLOW : EW_GREEN;
      EW_YELLOW:  next_state = train_valid ? NS_GREEN : EW_YELLOW;
      default:    next_state = NS_GREEN;
  end

  // Output current state
  assign state = current_state;

endmodule

