module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  // State encoding parameters
  localparam [1:0] IDLE = 2'b00,
                   UP   = 2'b01,
                   DOWN = 2'b10,
                   ERROR = 2'b11;

  // Next state logic
  always @* begin
    case ({clk, areset, train_valid, train_taken})
      // Valid transitions from IDLE
      4'b1?0?: state = UP;    // clk=1, train_valid=0 → UP
      4'b0?0?: state = DOWN;  // clk=0, train_valid=0 → DOWN
      // Valid transitions from UP
      4'b110?: state = ERROR;  // clk=1, areset=1, train_valid=0 → ERROR
      4'b010?: state = ERROR;  // clk=0, areset=1, train_valid=0 → ERROR
      // Valid transitions from DOWN
      4'b?1?0: state = ERROR;  // areset=1, train_valid=0 → ERROR
      // Default to IDLE (and ERROR states are unreachable without valid transitions)
      default: state = IDLE;
    endcase
  end

endmodule

