module TopModule (
  input clk,
  input slowena,
  input reset,
  output reg [3:0] q
);

  // Define FSM states
  localparam [2:0]
    IDLE   = 3'b000,
    SCAN   = 3'b001,
    SHIFT  = 3'b010,
    TEST   = 3'b011,
    OUTPUT = 3'b100,
    DONE   = 3'b101;

  reg [2:0] current_state, next_state;
  reg [3:0] lfsr_reg;
  reg [3:0] scnt_reg;
  reg [3:0] mask_reg;
  reg [2:0] bit_counter;

  // State transition and LFSR scan logic
  always @(posedge clk) begin
    if (slowena) begin
      current_state <= IDLE;
      lfsr_reg <= 4'b1111;
      scnt_reg <= 4'b0;
      mask_reg <= 4'b0;
      bit_counter <= 3'b0;
    end else begin
      current_state <= next_state;

      case (current_state)
        IDLE: begin
          lfsr_reg <= 4'b1111;
          scnt_reg <= 4'b0;
          mask_reg <= 4'b0;
          bit_counter <= 3'b0;
        end

        SCAN: begin
          // Shift left and compute new XOR value
          lfsr_reg <= {lfsr_reg[2:0], 1'b0};
          scnt_reg <= {scnt_reg[2:0], lfsr_reg[3] ^ lfsr_reg[0]};

          if (reset) begin
            mask_reg <= scnt_reg;
            bit_counter <= bit_counter + 1;
          end
        end

        SHIFT: begin
          // Continue shifting left
          lfsr_reg <= {lfsr_reg[2:0], 1'b0};
        end

        TEST: begin
          // Check if all bits are zero
          if (lfsr_reg == 4'b0)
            current_state <= DONE;
          else
            current_state <= SCAN;
        end

        OUTPUT: begin
          q <= lfsr_reg;
          current_state <= DONE;
        end

        DONE: begin
          // Exit TopModule
          current_state <= DONE;
        end

        default: current_state <= IDLE;
      endcase
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE:   next_state = SCAN;
      SCAN:   next_state = (reset) ? SHIFT : SCAN;
      SHIFT:  next_state = TEST;
      TEST:   next_state = (lfsr_reg == 4'b0) ? OUTPUT : SCAN;
      OUTPUT: next_state = DONE;
      DONE:   next_state = DONE;
      default: next_state = IDLE;
    endcase
  end

endmodule

