      q <= 1'b0;
    end else begin
      if (counter < 5'd16) begin
        q <= captured_data[counter];
        counter <= counter + 1;
      end else begin
        q <= captured_data[15];
      end
    end
  end

  // Note: Capturing data requires a separate input stream not provided in the interface.
  // This code assumes captured_data is externally populated, which is not standard for SCI.

endmodule

module TopModule (
  input clk,
  input d,
  output reg q
);

  localparam STATE_IDLE = 2'b00;
  localparam STATE_PREPARE = 2'b01;
  localparam STATE_WAIT = 2'b10;

  reg [1:0] state, next_state;
  reg [31:0] counter;
  reg [31:0] data_buffer;
  reg data_available;

  // State transition and data handling logic
  always @(posedge clk) begin
    if (d) begin
      state <= STATE_IDLE;
      counter <= 0;
      data_buffer <= 0;
      data_available <= 0;
      q <= 0;
    end else begin
      state <= next_state;

      case (state)
        STATE_IDLE: begin
          q <= 0;
          if (!data_available) begin
            counter <= 0;
            data_buffer <= 0;
            data_available <= 1;
          end
        end

        STATE_PREPARE: begin
          q <= 1;
          data_buffer <= data_buffer + 1;
          data_available <= 0;
        end

        STATE_WAIT: begin
          q <= 1;
          if (counter == 32'd15) begin
            q <= 0;
            data_available <= 1;
            counter <= 0;
          end else begin
            counter <= counter + 1;
          end
        end

        default: begin
          state <= STATE_IDLE;
          q <= 0;
        end
      endcase
    end
  end

  // Next state logic
  always @(*) begin
    case (state)
      STATE_IDLE: next_state = STATE_PREPARE;
      STATE_PREPARE: next_state = STATE_WAIT;
      STATE_WAIT: next_state = (counter == 32'd15) ? STATE_IDLE : STATE_WAIT;
      default: next_state = STATE_IDLE;
    endcase
  end

endmodule

module TopModule (
  input clk,
  input d,
  output reg q
);

  parameter DIVISOR = 4'd8;

  localparam WIDTH = (DIVISOR == 1) ? 1 : ($clog2(DIVISOR-1) + 1);
  reg [WIDTH-1:0] cuenta;

  always @(posedge clk) begin
    if (d) begin
      cuenta <= 0;
      q <= 0;
    end else begin
      if (cuenta == DIVISOR - 1) begin
        cuenta <= 0;
        q <= 1;
      end else begin
        cuenta <= cuenta + 1;
        q <= 0;
      end
    end
  end

endmodule

module TopModule (
  input clk,
  input d,
  output reg q
);

  reg [31:0] pc;
  reg [31:0] instr;
  reg [31:0] reg_file [0:31];
  reg [31:0] data_mem [0:1023];
  reg halt;

  wire [31:0] read_data1, read_data2;
  wire [31:0] sign_ext_imm;
  wire [31:0] offset_6to12;
  wire [31:0] offset_6to12_shifted;
  wire [31:0] jump_target;
  wire [31:0] pc_plus4;

  // IF: Instruction Fetch
  always @(posedge clk) begin
    if (!halt) begin
      pc <= pc + 4;
      instr <= data_mem[pc[11:2]]; // Word-aligned
    end
  end

  // ID: Instruction Decode
  assign read_data1 = reg_file[instr[31:26]]; // rs
  assign read_data2 = reg_file[instr[25:20]]; // rt
  assign sign_ext_imm = {{20{instr[19]}}, instr[19:0]}; // Sign-extend 20-bit offset
  assign offset_6to12 = instr[19:6]; // 12-bit offset
  assign offset_6to12_shifted = offset_6to12 << 2; // Multiply by 4
  assign jump_target = pc + sign_ext_imm;
  assign pc_plus4 = pc + 4;

  // EX: Execute
  wire [31:0] result1 = read_data1 + read_data2;
  wire [31:0] result2 = read_data1 - read_data2;
  wire [31:0] result3 = sign_ext_imm;
  wire [31:0] result4 = 32'h0;
  wire [31:0] result5 = data_mem[result2[11:2]]; // Load from memory

  // MEM: Memory Access
  wire [1023:0] mem_segment = data_mem[pc[11:2]]; // Word-aligned segment

  // WB: Write Back
  reg [31:0] write_data;
  reg [25:0] write_dest;

  always @(posedge clk) begin
    if (!halt) begin
      case (instr[31:26])
        6'b000000: begin // R-type
          write_dest = instr[25:20];
          case (instr[5:0])
            6'b100000: write_data = result1; // add
            6'b100010: write_data = result2; // sub
            default: write_data = 0;
          endcase
          reg_file[write_dest] <= write_data;
        end
        6'b000001: reg_file[instr[25:20]] <= result3; // Immediate
        6'b000010: reg_file[instr[25:20]] <= result4; // Zero
        6'b000011: reg_file[instr[25:20]] <= result5; // Memory
        6'b000100: // Branch (conditional)
          if (result1[result31]) // Assume signed comparison
            pc <= jump_target;
        6'b000101: // Jump
          pc <= jump_target;
        default: ; // Other instructions
      endcase
    end
  end

  // Halt Detection
  always @(posedge clk) begin
    if (instr[31:26] == 6'b111111) // HLT opcode
      halt <= 1;
  end

  // Output ALU Result
  always @(*) begin
    q = (instr[31:26] == 6'b000000) ? result1[result31] :
             (instr[31:26] == 6'b000001) ? result3[result31] :
             (instr[31:26] == 6'b000010) ? result4[result31] :
             (instr[31:26] == 6'b000011) ? result5[result31] : 0;
  end

endmodule

module TopModule (
  input clk,
  input d,
  output reg q
);

  parameter MODE_SINK = 1'b0;
  parameter MODE_SOURCE = 1'b1;

  reg current_mode;
  reg prev_input;

  // Capture the current mode when d is high
  always @(d) begin
    if (d) begin
      current_mode <= clk;
    end
  end

  // Detect changes in clk when d is high
  wire change_detected;
  assign change_detected = d && (clk != current_mode);

  // Previous value of clk during high d
  reg prev_input;
  always @(posedge d) begin
    prev_input <= clk;
  end

  // Determine push or pop based on current mode and clk change
  wire action;
  assign action = (current_mode == MODE_SINK) ? 
                   ((prev_input && !clk) ? 1'b1 : 1'b0) : 
                   (!prev_input && clk ? 1'b1 : 1'b0);

  // Update q output
  always @(posedge d) begin
    q <= action;
  end

endmodule

