module TopModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);

  // State definitions
  localparam [2:0] 
    IDLE      = 3'b000,
    SETMIN    = 3'b001,
    SETONOFF  = 3'b010,
    SETTIME   = 3'b011,
    ERROR     = 3'b100;

  reg [2:0] current_state, next_state;
  reg [2:0] seq_counter;
  reg [31:0] set_min_reg;
  reg [31:0] set_onoff_reg;
  reg [5:0] set_time_high, set_time_low;
  reg [31:0] set_time_reg;

  // Clock generation for state transitions (1Hz)
  reg clk_1hz;
  always #31 clk_1hz = ~clk_1hz;

  // State transition and sequential logic
  always @(posedge clk_1hz or posedge clk) begin
    if (clk) begin
      current_state <= IDLE;
      seq_counter <= 0;
      set_min_reg <= 0;
      set_onoff_reg <= 0;
      set_time_high <= 0;
      set_time_low <= 0;
      set_time_reg <= 0;
      Z <= 0;
    end else begin
      current_state <= next_state;
      seq_counter <= (current_state != next_state) ? 0 : seq_counter + 1;

      // Capture inputs when entering each state
      case (current_state)
        IDLE: if (enable) seq_counter <= 0;
        SETMIN: if (A) set_min_reg <= {32{B}};
        SETONOFF: if (B) set_onoff_reg <= {32{C}};
        SETTIME: begin
          if (B) begin
            set_time_high <= {26{C}}, C;
            set_time_low <= {26{C}}, C;
          end
          set_time_reg <= {set_time_high, set_time_low};
        end
        default: ;
      endcase

      // Error detection and Z output
      Z <= (next_state == ERROR) ? 1'b1 : 1'b0;
    end
  end

  // Next state logic
  always @* begin
    next_state = current_state;
    case (current_state)
      IDLE: if (enable) next_state = SETMIN;
      SETMIN: if (seq_counter >= 3 && A) next_state = SETONOFF;
      SETONOFF: if (seq_counter >= 3 && B) next_state = SETTIME;
      SETTIME: if (seq_counter >= 6 && B) next_state = IDLE;
      ERROR: next_state = IDLE;
      default: next_state = IDLE;
    endcase
  end

endmodule

module TopModule (
