module TopModule (
  input clk,
  input j,
  input k,
  output reg Q
);

  reg [2:0] state, next_state;
  parameter [2:0] 
    IDLE  = 3'd0,
    START = 3'd1,
    DATA  = 3'd2,
    PARITY= 3'd3,
    STOP  = 3'd4;

  reg [7:0] data_reg;
  reg [2:0] bit_count;
  wire tx_ready;

  assign tx_ready = (state == IDLE);

  always @(posedge clk) begin
    if (j) begin
      state <= IDLE;
      data_reg <= 8'h00;
      bit_count <= 3'd0;
      Q <= 1'b1;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      IDLE:   next_state = tx_ready ? START : IDLE;
      START:  next_state = DATA;
      DATA:   next_state = (bit_count == 3'd7) ? PARITY : DATA;
      PARITY: next_state = STOP;
      STOP:   next_state = IDLE;
      default: next_state = IDLE;
    endcase
  end

  always @(posedge clk) begin
    if (j) begin
      data_reg <= 8'h00;
      bit_count <= 3'd0;
    end else if (state == DATA) begin
      bit_count <= bit_count + 1;
    end
  end

  always @(posedge clk) begin
    if (j) begin
      Q <= 1'b1;
    end else begin
      case (state)
        IDLE:   Q <= 1'b1;
        START:  Q <= 1'b0;
        DATA:   Q <= data_reg[7];
        PARITY: Q <= 1'b0;
        STOP:   Q <= 1'b1;
        default: Q <= 1'b1;
      endcase
    end
  end

  always @(posedge clk) begin
    if (k)
      data_reg <= Q;
  end

