      sync_trig_d <= 2'b0;
      sync_ce_s <= 2'b0;
      sync_ce_d <= 2'b0;
    end else begin
      sync_trig_s <= {sync_trig_s[0], k};
      sync_trig_d <= {sync_trig_s[1], 1'b0};
      sync_ce_s <= {sync_ce_s[0], Q};
      sync_ce_d <= {sync_ce_s[1], 1'b0};
    end
  end

  // Combine synchronized signals and enforce Q >= k
  wire combined = sync_trig_d[1] | sync_ce_d[1];
  always @(*) begin
    Q = combined & ~k;
