  parameter [2:0] IDLE  = 3'b000,
                  READ1 = 3'b001,
                  READ2 = 3'b010,
                  READ3 = 3'b011,
                  READ4 = 3'b100,
                  READ5 = 3'b101,
                  READ6 = 3'b110,
                  READ7 = 3'b111;

  reg [2:0] state, next_state;
  reg [21:0] counter; // Sufficient to count up to 1,000,000 (22 bits)

  // State transition and counter logic
  always @(posedge aresetn) begin
    if (x) begin
      state <= IDLE;
      counter <= 0;
    end else begin
      state <= next_state;
      if (state != IDLE)
        counter <= counter + 1;
      else
        counter <= 0;
    end
  end

  // Next state logic
  always @(*) begin
    case (state)
      IDLE:   next_state = (clk) ? READ1 : IDLE;
      READ1:  next_state = (counter == 22'd999999) ? READ2 : READ1;
      READ2:  next_state = (counter == 22'd999999) ? READ3 : READ2;
      READ3:  next_state = (counter == 22'd999999) ? READ4 : READ3;
      READ4:  next_state = (counter == 22'd999999) ? READ5 : READ4;
      READ5:  next_state = (counter == 22'd999999) ? READ6 : READ5;
      READ6:  next_state = (counter == 22'd999999) ? READ7 : READ6;
      READ7:  next_state = (counter == 22'd999999) ? IDLE : READ7;
      default: next_state = IDLE;
    endcase
  end

  // Output logic
  always @(*) begin
    z = (state == READ7);
  end

