    sck_sync <= {sck_sync[0], areset};
    data_sync <= {data_sync[0], in};
  end

  // Generate prev_sck
  always @(posedge clk) begin
    prev_sck <= sck_sync[1];
  end

  // Detect data rising/falling edges
  assign data_rising = (data_sync[1] && ~data_sync[0]);
  assign data_falling = (~data_sync[1] && data_sync[0]);

  // Determine sample and shift events
  assign sample_event = (prev_sck != sck_sync[1]) && (sck_sync[1] == data_sync[0]);
  assign shift_reg_en = (prev_sck != sck_sync[1]) && (sck_sync[1] != data_sync[0]);
  assign load_event = (sck_sync[1] == data_sync[0]) && (prev_sck == data_sync[0]);

  // Shift register logic
  reg [7:0] shift_reg;
  always @(posedge clk) begin
    if (load_event)
      shift_reg <= 8'hFF;
    else if (shift_reg_en)
      shift_reg <= {shift_reg[6:0], data_sync[1]};
  end

  // Output logic
  assign out = in ? 1'b0 :
               (sample_event ? shift_reg[7] : 1'b0);

endmodule

