    if (in) begin
      s1 <= 2'b00;
    end else begin
      s1[0] <= areset;
      s1[1] <= areset & ~s1[0];
    end
  end

  // Second stage flip-flops
  always @(posedge clk or posedge in) begin
    if (in) begin
      s2 <= 2'b00;
    end else begin
      s2[0] <= s1[0];
      s2[1] <= s1[1] & ~s2[0];
    end
  end

  assign out = s2[1];
