  localparam HOLD_STATE  = 1'b0;
  localparam CLEAR_STATE = 1'b1;
`endif

reg current_state;
wire next_state;

// Next state logic
assign next_state = (reset && !k) ? SET_STATE :
                   (k && !reset) ? CLEAR_STATE :
                   (j && (current_state != HOLD_STATE)) ? SET_STATE :
                   (clk && (current_state != RESET_STATE)) ? RESET_STATE :
                   current_state;

// State register
always @(posedge k) begin
  if (reset)
    current_state <= RESET_STATE;
  else
