  // State register with synchronous reset
  always @(posedge in or posedge reset) begin
    if (reset)
      current_state <= RESET_STATE;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      RESET_STATE: 
        next_state = clk ? SET_STATE : RESET_STATE;
      SET_STATE:
        next_state = clk ? SET_STATE : RESET_STATE;
      default:
