  output out_and,
  output out_or,
  output out_xor,
  output out_nand,
  output out_nor,
  output out_xnor,
  output out_anotb
);

  reg [6:0] q;

  always @(posedge a or negedge b) begin
    if (!b) begin
      q <= 7'b0000000;
    end else begin
      // Feedback logic: Each bit is XOR of two previous bits
      q <= {q[5] ^ q[6], q[4] ^ q[5], q[3] ^ q[4], q[2] ^ q[3], q[1] ^ q[2], q[0] ^ q[1], q[6] ^ q[0]};
    end
  end

  assign {out_and, out_or, out_xor, out_nand, out_nor, out_xnor, out_anotb} = q;

endmodule

