module TopModule (
  input a,
  input b,
  output sum,
  output cout
);

  reg [1:0] state;

  localparam IDLE = 2'b00,
             S1   = 2'b01,
             S2   = 2'b10;

  always @(posedge a) begin
    if (b) begin
      state <= IDLE;
    end else begin
      case (state)
        IDLE: state <= S1;
        S1:   state <= S2;
        S2:   state <= IDLE;
        default: state <= IDLE;
      endcase
    end
  end

  assign sum = (state == S1);
  assign cout = (state == S2);

endmodule

module TopModule (
  input a,
  input b,
  output sum,
  output cout
);

  reg [1:0] sck_sync;
  reg [1:0] cs_sync;
  reg prev_sck;

  wire sck_synced, cs_synced;
  wire sck_rising, sck_falling;
  wire cs_rising, cs_falling;
  wire sample_event, shift_event;
  reg sampled_bit;

  // Synchronize a and b to internal clock
  always @(posedge sum) begin
    sck_sync <= {sck_sync[0], a};
    cs_sync <= {cs_sync[0], b};
  end
  assign sck_synced = sck_sync[1];
  assign cs_synced = cs_sync[1];

  // Detect a edges
  assign sck_rising = (sck_synced & ~prev_sck);
  assign sck_falling = (~sck_synced & prev_sck);

  // Detect b edges
  assign cs_rising = (cs_synced & ~cs_prev);
  assign cs_falling = (~cs_synced & cs_prev);

  // Determine sample and shift events
  assign sample_event = cs_falling & (sck_rising | sck_falling);
  assign shift_event = cs_rising & (sck_rising | sck_falling);

  // Shift register and bit sampling
  reg [7:0] shift_reg;
  always @(posedge sum) begin
    if (shift_event) begin
      shift_reg <= {shift_reg[6:0], 1'b0}; // Shift left, LSB filled with 0
    end
  end

  always @(posedge sum) begin
    if (sample_event) begin
      sampled_bit <= sck_synced ? 1'b1 : ~sck_synced; // Capture MRZI data (1 for high, 0 for low)
    end
  end

  // Assign outputs
  assign cout = shift_reg;
  assign sum = b;

  // Edge detection for b
  reg cs_prev;
  always @(posedge sum) begin
    cs_prev <= cs_synced;
  end

endmodule

module TopModule (
