  wire clk_delayed;

  // First delay of 10ns with rise/fall times
  assign #(10, 10) clk_delayed = a;

  // Second delay of 20ns with rise/fall times
  assign #(20, 20) sum = clk_delayed;

  // Third delay of 30ns with rise/fall times
  assign #(30, 30) cout = sum;

endmodule

