  reg [3:0] state;

  always @(posedge d or posedge ena) begin
    if (ena) begin
      state <= INIT;
    end else begin
      state <= {state[2:0], state[3] ^ state[2] ^ state[1]};
    end
  end

  assign q = state[3];

