      J: next_state = K;
      K: next_state = L;
      L: next_state = M;
      M: next_state = N;
      N: next_state = O;
      O: next_state = P;
      P: next_state = A;
      default: next_state = A;
    endcase
  end

  // Output is 1 in states N and P
  always @(*) begin
    q = (current_state == N) || (current_state == P);
