  always @(posedge clk or negedge d) begin
    if (!d) begin
      current_state <= IDLE;
      clock_pulse_count <= 2'b0;
    end else begin
      current_state <= next_state;
      if (current_state == S6) begin
        clock_pulse_count <= clock_pulse_count + 1;
      end else begin
        clock_pulse_count <= 2'b0;
      end
    end
  end

  // Combinational logic for next state and output
  always @(*) begin
    case (current_state)
