      S1: next_state = r ? S1 : S2;
      S2: next_state = r ? S1 : S3;
      S3: next_state = r ? S1 : S4;
      S4: next_state = r ? S1 : S5;
      S5: next_state = r ? S1 : S6;
      S6: next_state = r ? S1 : IDLE;
      default: next_state = IDLE;
    endcase
  end

  // Output logic: q is high when in S6 and clock_pulse_count is 3 (4 cycles)
  assign q = (current_state == S6) && (clock_pulse_count == 2'd3);

