             S6 = 3'd6,
             S7 = 3'd7;

  reg [2:0] current_state, next_state;
  reg [15:0] counter;
  localparam MAX_COUNT = 16'd10000; // Adjust based on required debounce time

  // State transition and counter logic
  always @(posedge in1) begin
    if (in2) begin
      current_state <= S0;
      counter <= 0;
    end else begin
      current_state <= next_state;
      if (current_state != next_state) begin
        counter <= 0;
      end else if (counter < MAX_COUNT) begin
        counter <= counter + 1;
      end
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      S0: next_state = (in2 && counter >= MAX_COUNT) ? S1 : S0;
      S1: next_state = (in2 && counter >= MAX_COUNT) ? S2 : (in2 ? S1 : S0);
      S2: next_state = (in2 && counter >= MAX_COUNT) ? S3 : (in2 ? S2 : S0);
      S3: next_state = (in2 && counter >= MAX_COUNT) ? S4 : (in2 ? S3 : S0);
      S4: next_state = (in2 && counter >= MAX_COUNT) ? S5 : (in2 ? S4 : S0);
      S5: next_state = (in2 && counter >= MAX_COUNT) ? S6 : (in2 ? S5 : S0);
      S6: next_state = (in2 && counter >= MAX_COUNT) ? S7 : (in2 ? S6 : S0);
      S7: next_state = in2 ? S7 : S0;
      default: next_state = S0;
    endcase
  end

  // Output logic
  always @(*) begin
    out = (current_state == S7) ? 1'b1 : 1'b0;
