  wire [3:0] carry;

  // Compute each sum bit using AND, OR, NOT gates
  assign sum_bits[0] = (x[0] & y[0]) | ((~x[0]) & (~y[0]));
  assign sum_bits[1] = (x[1] & y[1]) | ((~x[1]) & (~y[1]));
  assign sum_bits[2] = (x[2] & y[2]) | ((~x[2]) & (~y[2]));
  assign sum_bits[3] = (x[3] & y[3]) | ((~x[3]) & (~y[3]));

  // Compute carry signals using OR gates
  assign carry[0] = sum_bits[0] | carry[0]; // carry[0] is 0 (initialized)
  assign carry[1] = sum_bits[1] | carry[0];
  assign carry[2] = sum_bits[2] | carry[1];
  assign carry[3] = sum_bits[3] | carry[2];

  // Concatenate carry and sum bits to form the 5-bit sum
  assign sum = {carry[3], sum_bits};

