  output [4:0] sum
);

  wire [3:0] F;  // Intermediate signal array of size 4
  wire [3:0] G;  // Intermediate signal array of size 4
  wire [4:0] temp_sum;

  // Generate intermediate signals F and G using AND gates
  genvar i;
  generate
    for (i = 0; i < 4; i = i + 1) begin : fg_gen
      and (F[i], x[i], y[i]);
      and (G[i], x[i], ~y[i]);
    end
  endgenerate

  // Compute temporary sum using adder
  assign temp_sum = {1'b0, F} + {1'b0, G};

  // Assign final output with 5-bit precision
  assign sum = temp_sum;

endmodule

