  input b,
  output out
);

`ifdef TIMER_1HZ
  // 1Hz timer: divide by 2 (50% duty cycle)
  assign out = a ? ~b : b;
`elsif TIMER_2HZ
  // 2Hz timer: divide by 4 (66.67% duty cycle)
  reg [1:0] counter;
  always @(posedge a) begin
    if (b) begin
      counter <= (counter == 2'd3) ? 2'd0 : counter + 1;
    end else begin
      counter <= 2'd0;
    end
  end
  assign out = b && (counter < 2'd4);
`elsif TIMER_5HZ
  // 5Hz timer: divide by 8 (62.5% duty cycle)
  reg [2:0] counter;
  always @(posedge a) begin
    if (b) begin
      counter <= (counter == 3'd7) ? 3'd0 : counter + 1;
    end else begin
      counter <= 3'd0;
    end
  end
  assign out = b && (counter < 3'd8);
`else
  // Default: 1Hz behavior (divide by 2)
  assign out = a ? ~b : b;
`endif

endmodule

