  reg [7:0] shifted;

  assign out = bcd_reg[1:0];

  always @* begin
    bcd_reg = in;
    shifted = 8'b0;

    // Process bit 2 (MSB)
    shifted = {shifted[6:0], 1'b0};
    if (shifted[7] & bcd_reg[2])
      shifted[7:6] = shifted[7:6] + 3;

    // Process bit 1
    shifted = {shifted[6:0], 1'b0};
    if (shifted[6] & bcd_reg[1])
      shifted[6:5] = shifted[6:5] + 3;

    // Process bit 0 (LSB)
    shifted = {shifted[6:0], 1'b0};
    if (shifted[5] & bcd_reg[0])
      shifted[5:4] = shifted[5:4] + 3;
