module TopModule (
  input clk,
  input shift_ena,
  input count_ena,
  input data,
  output reg [3:0] q
);

  wire [1:0] hsync_sync = {count_ena, count_ena};
  wire vsync_sync = data;

  wire hsync_sync_rst = hsync_sync[1] & hsync_sync[0];
  wire vsync_sync_rst = vsync_sync & hsync_sync[0];
  wire reset = hsync_sync_rst | vsync_sync_rst;

  reg [3:0] cbo_r;
  reg [3:0] cbo_prev;
  wire cbo_rise;

  // Clock Bit Optimizer (CBO) logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      cbo_r <= 4'b0000;
    end else begin
      cbo_r[0] <= shift_ena;
      if (shift_ena) begin
        cbo_r[1] <= cbo_r[0];
      end else if (data) begin
        cbo_r[2] <= cbo_r[1];
      end else if (count_ena) begin
        cbo_r[3] <= cbo_r[2];
      end
    end
  end

  assign cbo_rise = cbo_r[0] & ~cbo_prev;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      cbo_prev <= 1'b0;
      q <= 4'b0000;
    end else begin
      cbo_prev <= cbo_r[3];
      if (cbo_rise) begin
        q <= q + 1;
      end
    end
  end

endmodule

