      D_reg = 4'bxxxx;
    else case (stage)
      2'b00: D_reg = data;        // No branches
      2'b01: D_reg = {D_reg[2:0], ena}; // clk taken
      2'b10: D_reg = {areset, D_reg[3:1]}; // areset taken
      2'b11: D_reg = {data[2:0], ena}; // Both taken (invalid, but handled)
      default: D_reg = data;
    endcase
  end

  always @(posedge clk) begin
    if (load)
      q <= 4'bxxxx;
    else
      q <= D_reg;
  end

endmodule

module TopModule (
  input clk,
  input areset,
  input load,
  input ena,
  input [3:0] data,
  output reg [3:0] q
);

  // State definitions
  localparam [1:0] IDLE  = 2'b00,
                   LOAD  = 2'b01,
                   SHIFT = 2'b10,
                   DONE  = 2'b11;

  reg [1:0] current_state, next_state;
  reg [3:0] Q_reg;

  // State register and Q_reg update
  always @(posedge clk) begin
    if (areset) begin
      current_state <= IDLE;
      Q_reg <= 4'b0;
    end else begin
      current_state <= next_state;
      Q_reg <= q;
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE:  next_state = load ? LOAD : IDLE;
      LOAD:  next_state = SHIFT;
      SHIFT: next_state = (data == 4'b0) ? DONE : SHIFT;
      DONE:  next_state = load ? LOAD : DONE;
      default: next_state = IDLE;
    endcase
  end

  // Output logic
  always @(*) begin
    case (current_state)
      IDLE:  q = 4'b0000;
      LOAD:  q = data;
      SHIFT: q = Q_reg >> 1;
      DONE:  q = 4'b0000;
      default: q = 4'b0000;
    endcase
  end

endmodule

