module TopModule (
  input clk,
  input areset,
  input load,
  input ena,
  input [3:0] data,
  output reg [3:0] q
);

  // State definitions
  localparam [3:0]
    IDLE_STATE  = 4'b0001,
    LOAD_STATE  = 4'b0010,
    INC_STATE   = 4'b0100,
    DEC_STATE   = 4'b1000;

  reg [3:0] current_state, next_state;

  // State register
  always @(posedge clk) begin
    if (areset)
      current_state <= IDLE_STATE;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    next_state = current_state; // Default: stay in current state
    case (1'b1)
      load: next_state = LOAD_STATE;
      ena: begin
        case (current_state)
          INC_STATE: next_state = DEC_STATE;
          DEC_STATE: next_state = INC_STATE;
          default: next_state = IDLE_STATE;
        endcase
      end
      data: next_state = IDLE_STATE;
      default: next_state = current_state;
    endcase
  end

  // Output logic
  always @(*) begin
    q = current_state;
  end

endmodule

