module TopModule (
  input mode,
  input too_cold,
  input too_hot,
  input fan_on,
  output heater,
  output aircon,
  output fan
);

  reg [1:0] current_state, next_state;
  reg [1:0] prev_state;

  parameter UP = 2'd0;
  parameter DOWN = 2'd1;
  parameter LEFT = 2'd2;
  parameter RIGHT = 2'd3;

  // State transition and previous state storage
  always @(posedge mode) begin
    if (too_cold) begin
      current_state <= UP;
      prev_state <= UP;
    end else begin
      prev_state <= current_state;
      current_state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    next_state = current_state;
    if (too_hot || fan_on) begin
      case (current_state)
        UP: begin
          if (fan_on)
            next_state = RIGHT;
          else if (too_hot)
            next_state = LEFT;
        end
        DOWN: begin
          if (fan_on)
            next_state = RIGHT;
          else if (too_hot)
            next_state = LEFT;
        end
        LEFT: begin
          if (fan_on)
            next_state = UP;
          else if (too_hot)
            next_state = DOWN;
        end
        RIGHT: begin
          if (fan_on)
            next_state = RIGHT;
          else if (too_hot)
            next_state = LEFT;
        end
        default: next_state = UP;
      endcase
    end
  end

  // Output logic with reset override
  assign heater = too_cold ? 1'b0 : (current_state == prev_state);
  assign aircon = too_cold ? 1'b0 : (current_state == LEFT);
  assign fan = too_cold ? 1'b0 : (current_state == RIGHT);

endmodule

module TopModule (
  input mode,
  input too_cold,
  input too_hot,
  input fan_on,
  output heater,
  output aircon,
  output fan
);

  reg [7:0] r;

  always @(posedge mode) begin
    if (too_cold)
      r <= 8'b0;
    else begin
      reg [7:0] next_r;
      next_r = {r[6:0], 1'b0}; // Shift left, insert 0 at LSB
      if (too_hot)
        next_r[7] = fan_on; // Update MSB with fan_on
      r <= next_r;
    end
  end

  assign heater = r[7];
  assign aircon = r[6];
  assign fan = r[5];

endmodule

module TopModule (
  input mode,
  input too_cold,
  input too_hot,
  input fan_on,
  output heater,
  output aircon,
  output fan
);

  // Register Clock Generation using feedback loop
  reg register_clk;
  always @(posedge mode or posedge too_cold) begin
    if (too_cold)
      register_clk <= 1'b0;
    else
      register_clk <= too_hot ? register_clk : 1'b1;
  end
  assign aircon = register_clk;

  // Master-T Slave Latch for fan_on synchronization
  reg master_q, slave_q;

  // Master latch (enabled when mode is high)
  always @(*) begin
    if (mode) begin
      if (too_hot)
        master_q = 1'b1;
      else if (fan_on)
        master_q = 1'b0;
    end
  end

  // Slave latch (enabled when mode is low)
  always @(*) begin
    if (!mode) begin
      if (too_hot)
        slave_q = master_q;
      else if (fan_on)
        slave_q = ~master_q;
    end
  end
  assign heater = slave_q;

  // Scan chain propagation using slave latch
  reg [N-1:0] scan_chain;
  integer i;

  // Initialize scan chain (assuming too_cold initializes to 0)
  always @(posedge mode or posedge too_cold) begin
    if (too_cold)
      scan_chain <= {N{1'b0}};
  end

  // Shift chain when mode is low and too_hot is high
  always @(*) begin
    if (!mode && too_hot)
      scan_chain <= {scan_chain[N-1:1], 1'b1}; // Assuming clock adds 1
  end

  assign fan = scan_chain[N-1];

endmodule

module TopModule (
  input mode,
  input too_cold,
  input too_hot,
  input fan_on,
  output heater,
  output aircon,
  output fan
);

  reg [1:0] current_state, next_state;
  parameter [1:0] NO_GRANT = 2'b00,
                   M0_GRANT = 2'b01,
                   M1_GRANT = 2'b10,
                   M2_GRANT = 2'b11;

  // Next state logic
  always @(*) begin
    if (fan_on)
      next_state = M2_GRANT;
    else if (too_hot)
      next_state = M1_GRANT;
    else if (too_cold)
      next_state = M0_GRANT;
    else
      next_state = NO_GRANT;
  end

  // State register with synchronous reset
  always @(posedge mode) begin
    if (too_cold)
      current_state <= NO_GRANT;
    else
      current_state <= next_state;
  end

  // Output assignments (combinational)
  assign heater = (current_state == M0_GRANT);
  assign aircon = (current_state == M1_GRANT);
  assign fan = (current_state == M2_GRANT);

endmodule

module TopModule (
  input [2:0] vec,
  output [2:0] outv,
  output o2,
  output o1,
  output o0
);

  wire [2:0] c2;

  // Compute c2[0]
  wire term1_c2_0 = vec[0] & vec[1];
  wire term2_c2_0 = vec[2] & vec[2]; // Second AND term for c2[0]
  assign c2[0] = term1_c2_0 | term2_c2_0;

  // Compute c2[1]
  wire term1_c2_1 = vec[0] & vec[2];
  wire term2_c2_1 = vec[1] & vec[1]; // Second AND term for c2[1]
  assign c2[1] = term1_c2_1 | term2_c2_1;

  // Compute c2[2]
  wire term1_c2_2 = vec[0] & vec[1];
  wire term2_c2_2 = vec[1] & vec[2];
  wire term3_c2_2 = vec[0] & vec[2]; // Third AND term for c2[2]
  assign c2[2] = term1_c2_2 | term2_c2_2 | term3_c2_2;

  // Assign outputs
  assign outv = c2;
  assign o2 = c2[0];
  assign o1 = c2[1];
  assign o0 = c2[2];

endmodule

module TopModule (
  input [2:0] vec,
  output [2:0] outv,
  output o2,
  output o1,
  output o0
);

  reg [2:0] decoded_b;

  // Decode vec to 3-bit decoded_b using case statement
  always @(*) begin
    case (vec)
      1'd0: decoded_b = 3'b000;
      1'd1: decoded_b = 3'b001;
      1'd2: decoded_b = 3'b010;
      1'd3: decoded_b = 3'b011;
      1'd4: decoded_b = 3'b100;
      1'd5: decoded_b = 3'b101;
      1'd6: decoded_b = 3'b110;
      1'd7: decoded_b = 3'b111;
      default: decoded_b = 3'b000; // Handles invalid vec inputs
    endcase
  end

  // Compute outv by shifting decoded_b left by 1 (multiply by 2)
  assign outv = {decoded_b[1:0], decoded_b[2]};

  // Error flags are always 0
  assign o2 = 1'b0;
  assign o1 = 1'b0;
  assign o0 = 1'b0;

endmodule

