module TopModule (
  input [2:0] vec,
  output [2:0] outv,
  output o2,
  output o1,
  output o0
);

  wire [2:0] f_1;

  // Circuit A: AND followed by NOT (using NOR)
  assign f_1[0] = ~(vec[0] & vec[1]);
  assign f_1[1] = ~(vec[1] & vec[2]);
  assign f_1[2] = ~(vec[2] & vec[0]);

  // Circuit B: NOR of all inputs
  assign o2 = ~(vec[0] | vec[1] | vec[2]);

  // Circuit C: AND followed by OR (using NOR)
  assign o1[0] = ~(vec[0] & vec[1]);
  assign o1[1] = ~(vec[1] & vec[2]);
  assign o1[2] = ~(vec[2] & vec[0]);
  assign o0 = ~(o1[0] | o1[1] | o1[2]);

  assign outv = f_1;

