  assign temp1 = ~(a | b);
  assign temp2 = ~(a | temp1);
  assign temp3 = ~(b | temp1);
  assign w = ~(temp2 | temp3);

  // Compute x using NOR gates
  assign temp1 = ~(a | b);
  assign temp2 = ~(a | temp1);
  assign temp3 = ~(b | temp1);
  assign temp4 = ~(temp2 | temp3);
  assign x = ~temp4;

  // Compute y using NAND gates
  assign temp1 = ~(a & b);
  assign y = ~(temp1 & temp1);

  // Compute z using NOR gates
  assign temp1 = ~(a | b);
  assign temp2 = ~(temp1 | temp1);
  assign z = ~(temp2 | temp2);

endmodule

