  parameter [1:0] IDLE = 2'b00,
                   START = 2'b01,
                   DATA = 2'b10,
                   PARITY = 2'b11;

  // State register
  always @(posedge d or posedge c) begin
    if (c)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE:   next_state = a ? START : IDLE;
      START:  next_state = DATA;
      DATA:   next_state = b ? PARITY : DATA;
      PARITY: next_state = IDLE;
      default: next_state = IDLE;
    endcase
  end

  // Output logic
  assign out = (current_state == START) || (current_state == DATA);
  assign out_n = (current_state == PARITY);

endmodule

