module TopModule (
  input clk,
  input x,
  input [2:0] y,
  output reg Y0,
  output reg z
);

  reg [2:0] current_state, next_state;

  // State transition and reset logic
  always @(posedge clk) begin
    if (x) begin
      current_state <= 3'b000;
    end else begin
      current_state <= next_state;
    end
  end

  // Next state logic based on current state and y
  always @* begin
    case (current_state)
      3'b000: next_state = (y != 3'b000) ? 3'b001 : 3'b000;
      3'b001: next_state = (y != 3'b000) ? 3'b010 : 3'b000;
      3'b010: next_state = (y != 3'b000) ? 3'b011 : 3'b000;
      3'b011: next_state = (y != 3'b000) ? 3'b100 : 3'b000;
      3'b100: next_state = (y != 3'b000) ? 3'b101 : 3'b000;
      3'b101: next_state = (y != 3'b000) ? 3'b110 : 3'b000;
      3'b110: next_state = (y != 3'b000) ? 3'b111 : 3'b000;
      3'b111: next_state = (y != 3'b000) ? 3'b000 : 3'b000;
      default: next_state = 3'b000;
    endcase
  end

  // Output logic for Y0 and z
  always @* begin
    Y0 = (current_state == 3'b111) && (y != 3'b000);
    z = (current_state == 3'b111) && (y == 3'b000);
  end

