  localparam RESumed = 2'b10;

  reg [1:0] state;

  always @(posedge clk) begin
    if (x) begin
      state <= RESumed;
      Y0 <= 0;
      z <= 0;
    end else begin
      case (state)
        STALLED: if (y[0]) state <= PAUSED;
        PAUSED: if (y[1]) state <= RESumed;
        RESumed: if (y[2]) state <= STALLED;
        default: state <= RESumed;
      endcase

      Y0 <= (state == PAUSED) ? 1'b1 : 1'b0;
      z <= (state == STALLED) ? 1'b1 : 1'b0;
    end
  end

endmodule

module TopModule (
