  // Key synchronous reset and state transition
  always @(posedge clk) begin
    if (x) begin
      state <= STATE_IDLE;
      debounce_counter <= 0;
      Y0 <= 0;
      z <= 0;
    end else begin
      state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    case (state)
      STATE_IDLE: begin
        next_state = (y[0] == 0) ? STATE_COUNTING : STATE_IDLE;
      end
      STATE_COUNTING: begin
        next_state = STATE_DEBOUNCE;
      end
      STATE_DEBOUNCE: begin
        if (debounce_counter >= DEBOUNCE_CYCLES) begin
          next_state = (y[0] == 0) ? STATE_COUNTING : STATE_IDLE;
        end else begin
          next_state = STATE_DEBOUNCE;
        end
      end
      default: next_state = STATE_IDLE;
    endcase
  end

  // Debounce counter
  always @(posedge clk) begin
    if (x) begin
      debounce_counter <= 0;
    end else begin
      if (state == STATE_DEBOUNCE) begin
        debounce_counter <= debounce_counter + 1;
      end else begin
        debounce_counter <= 0;
      end
    end
  end

  // Output logic
  always @(posedge clk) begin
    if (x) begin
      Y0 <= 0;
      z <= 0;
    end else begin
      case (state)
        STATE_COUNTING: begin
          Y0 <= (y[0] == 0) ? 1'b1 : 1'b0;
          z <= (y[0] == 0) ? 1'b1 : 1'b0;
        end
        default: begin
          Y0 <= 1'b0;
          z <= 1'b0;
        end
      endcase
    end
  end

endmodule

module TopModule (
