  output reg Y0,
  output reg z
);

  localparam [2:0] IDLE_STATE = 3'd0;
  localparam [2:0] START_BIT_STATE = 3'd1;
  localparam [2:0] DATA_BITS_STATE = 3'd2;
  localparam [2:0] STOP_BIT_STATE = 3'd3;

  localparam [2:0] CURRENT_STATE S;
  localparam [2:0] NEXT_STATE N;

  localparam [2:0] IDLE_STATE_X S_X;
  localparam [2:0] START_BIT_STATE_X S_X;
  localparam [2:0] DATA_BITS_STATE_X S_X;
  localparam [2:0] STOP_BIT_STATE_X S_X;

  assign S_X = IDLE_STATE;

  always @(posedge clk) begin
    if (x) begin
      S <= IDLE_STATE;
    end else begin
      S <= N;
    end
  end

  always @(*) begin
    case (S)
      IDLE_STATE: begin
        N = (y == IDLE_STATE_X) ? START_BIT_STATE : IDLE_STATE;
      end
      START_BIT_STATE: begin
        N = (y == START_BIT_STATE_X) ? DATA_BITS_STATE : START_BIT_STATE;
      end
      DATA_BITS_STATE: begin
        N = (y == DATA_BITS_STATE_X) ? STOP_BIT_STATE : DATA_BITS_STATE;
      end
      STOP_BIT_STATE: begin
        N = (y == STOP_BIT_STATE_X) ? IDLE_STATE : STOP_BIT_STATE;
      end
      default: N = IDLE_STATE;
    endcase
  end

  always @(*) begin
    z = (S == START_BIT_STATE) || (S == DATA_BITS_STATE) || (S == STOP_BIT_STATE);
  end

  always @(posedge clk) begin
    if (x) begin
      Y0 <= 1'b1;
    end else begin
      case (S)
        IDLE_STATE: Y0 <= 1'b1;
        START_BIT_STATE: Y0 <= 1'b0;
        DATA_BITS_STATE: Y0 <= y[2];
