    s1 = in[5:2];
    if (in[7:6] == 2'b11)
      s1 = 2'b11;
    else
      s1 = {s1[5:2], in[7:6]}; // Overflow correction

    // Second stage: divide by 4 again and handle overflow
    s2 = s1[3:2];
    if (s1[5:4] == 2'b11)
      s2 = 2'b11;
    else
      s2 = {s2[3:2], s1[5:4]}; // Overflow correction

    // Third stage: divide by 2 (right shift by 1) and handle overflow
    pos = s2[1:0];
    if (s2[3:2] == 2'b11)
      pos = 3'b111;
    else
      pos = {s2[3:2], s2[1:0]}; // Overflow correction
  end

