    endcase
  end

  // State register with synchronous reset
  always @(posedge clk) begin
    if (a)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  // Output logic
  assign q = (current_state == S0 || current_state == S2);
  assign state = (current_state == S1 || current_state == S3);

