  wire n_reset_sync1, n_reset_sync2;
  wire n_clear_sync1, n_clear_sync2;
  wire async_reset;
  wire n_reset;

  assign enable = b;

  // Synchronize reset signals
  assign n_reset_sync1 = ~a;
  assign n_reset_sync2 = n_reset_sync1;

  assign n_clear_sync1 = ~b;
  assign n_clear_sync2 = n_clear_sync1;

  // Generate async_reset (active high when counter is 0)
  assign async_reset = (clk == 1'b0) ? ~n_clear_sync2 : 1'b0;

  // Combine resets (active low when either input is asserted)
  assign n_reset = async_reset ? ~a : 1'b0;

  // Synchronizer chain for reset signals
  reg q1, q2;
  always @(posedge clk or negedge n_reset) begin
    if (!n_reset) begin
      q1 <= 1'b0;
      q2 <= 1'b0;
    end else begin
      q1 <= ~a;
      q2 <= q1;
    end
  end
  assign state = q2;

  // Synchronizer chain for clear signals
  reg q3, q4;
  always @(posedge clk or negedge n_reset) begin
    if (!n_reset) begin
      q3 <= 1'b0;
      q4 <= 1'b0;
    end else begin
      q3 <= ~b;
      q4 <= q3;
    end
  end
  assign q = q4;

