    reg [3:0] temp_g, temp_p;
    reg [2:0] pos;
    reg [3:0] temp_g_pos, temp_p_pos;
    reg [1:0] s_part;

    // Calculate temp_g and temp_p for e
    temp_g = 4'b0;
    temp_p = 4'b0;
    for (pos = 0; pos < 4; pos = pos + 1) begin
      if (e[pos]) begin
        if (temp_g != 1) temp_g = temp_g | d[pos];
        temp_p = temp_p & ~d[pos];
      end
    end
    s_part = { (temp_g != 1), (temp_p != 1) };
  end

  // Compute signal t
  always @(*) begin
    reg [3:0] temp_g2, temp_p2;
    reg [2:0] pos2;
    reg [3:0] temp_g2_pos, temp_p2_pos;
    reg [1:0] t_part;

    // Calculate temp_g2 and temp_p2 for a
    temp_g2 = 4'b0;
    temp_p2 = 4'b0;
    for (pos2 = 0; pos2 < 4; pos2 = pos2 + 1) begin
      if (a[pos2]) begin
        if (temp_g2 != 1) temp_g2 = temp_g2 | b[pos2];
        temp_p2 = temp_p2 & ~b[pos2];
      end
    end
    t_part = { (temp_g2 != 1), (temp_p2 != 1) };
  end

  // Determine s and t based on c
  always @(*) begin
    if (c == 4'b0) begin
      s = 2'b00;
      t = 2'b00;
    end else if (c[0]) begin
      s = s_part;
      t = 2'b00;
    end else if (c[1]) begin
      s = 2'b00;
      t = t_part;
    end else begin
      s = 2'b00;
      t = 2'b00;
    end
  end

  // Determine q based on s and t
  always @(*) begin
    case ({s, t})
      4'b0000: q = 4'b0000; // EQUIZ
      4'b0001: q = d;   // ISM
      4'b0010: q = ~d;  // ISN
      4'b0011: q = c;    // IR
      4'b0100: q = b;   // IZ
      4'b0101: q = ~b;  // IZN
      4'b0110: q = a;    // CR
      4'b0111: q = ~a;   // CN
      4'b1000: q = e;   // CS
      4'b1001: q = ~e;  // C SN
