  input c,
  output out
);

  reg [31:0] a;
  reg [31:0] y;
  reg [31:0] temp_sum;
  reg [7:0] counter;
  reg [31:0] sum_buffer;

  // Update sum_buffer with a on rising edge of a or c
  always @(posedge a or posedge c) begin
    if (c)
      sum_buffer <= a;
    else
      sum_buffer <= sum_buffer + a;
  end

  // Update y on falling edge of a or c
  always @(negedge a or posedge c) begin
    if (c)
      y <= 32'b0;
    else
      y <= temp_sum;
  end

  // Ripple carry adder in b domain
  always @(posedge b or posedge c) begin
    if (c) begin
      temp_sum <= 32'b0;
      counter <= 8'b0;
    end else begin
      if (counter < 8'd32) begin
        temp_sum <= temp_sum + y[(31 - counter):0];
        counter <= counter + 1;
      end
    end
  end

  assign out = temp_sum[31];

endmodule

module TopModule (
  input a,
  input b,
  input c,
  output out
);

  reg [1:0] current_state, next_state;

  parameter A = 2'b00,
             B = 2'b01,
             C = 2'b10,
             D = 2'b11;

  // State register with synchronous active-low reset
  always @(posedge a) begin
    if (~b)
      current_state <= A;
    else
      current_state <= next_state;
  end

  // Next state combinational logic
  always @(*) begin
    case (current_state)
      A: next_state = c ? B : A;
      B: next_state = c ? C : A;
      C: next_state = c ? D : A;
      D: next_state = c ? D : A;
      default: next_state = A;
    endcase
  end

  // Output logic (Moore machine)
  assign out = (current_state == D);

endmodule

module TopModule (
  input a,
  input b,
  input c,
  output out
);
  reg [2:0] shift_reg;

  always @(posedge a) begin
    if (b) begin
      shift_reg <= 3'b000;
    end else begin
      if (c == 1'b0) begin
        shift_reg <= {shift_reg[1:0], 1'b0};
      end else begin
        shift_reg <= {1'b0, shift_reg[2:1]};
      end
    end
  end

  assign out = shift_reg[0];
endmodule

module TopModule (
  input a,
  input b,
  input c,
  output out
);

`ifdef ACTIVE_HIGH
  localparam RESET_STATE = 1'b1;
  localparam SET_STATE   = 1'b0;
  localparam TIMER_STATE = 1'b1;
  localparam GET_STATE   = 1'b0;
`else
  localparam RESET_STATE = 1'b0;
  localparam SET_STATE   = 1'b1;
  localparam TIMER_STATE = 1'b0;
  localparam GET_STATE   = 1'b1;
`endif

reg state, next_state;
reg [3:0] counter;

assign out = (state == GET_STATE);

always @(*) begin
  case (state)
    RESET_STATE: next_state = a ? SET_STATE : RESET_STATE;
    SET_STATE:   next_state = a ? TIMER_STATE : SET_STATE;
    TIMER_STATE: next_state = a ? TIMER_STATE : GET_STATE;
    GET_STATE:   next_state = a ? SET_STATE : GET_STATE;
    default:     next_state = RESET_STATE;
  endcase
end

always @(posedge b) begin
  if (c) begin
    state <= RESET_STATE;
    counter <= 4'd0;
  end else begin
    state <= next_state;
    if (state == RESET_STATE || state == SET_STATE)
      counter <= 4'd0;
    else if (state == TIMER_STATE)
      counter <= counter + 1;
  end
end

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output out
);

