module TopModule (
  input a,
  input b,
  input c,
  input d,
  output out
);

  wire [3:0] data = {d, c, b, a};
  reg [3:0] reversed_data;

  always @* begin
    reversed_data = {data[0], data[1], data[2], data[3]};
  end

  assign out = (out) ? (data == reversed_data) : 1'b1;

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output out
);
  wire N10, N11, N12, N13, N14, N15, N16, N17, N18, N19, N20, N21, N22, N23, N24;

  assign N10 = ~b;
  assign N11 = N10 ^ c;
  assign N12 = ~N11;
  assign N13 = N12 ^ d;
  assign N14 = ~N13;
  assign N15 = N14 ^ a;
  assign N16 = ~N15;
  assign N17 = N16 ^ b;
  assign N18 = ~N17;
  assign N19 = N18 ^ c;
  assign N20 = ~N19;
  assign N21 = N20 ^ d;
  assign N22 = ~N21;
  assign N23 = N22 ^ a;
  assign N24 = ~N23;

  assign out = N24;
endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output out
);
  parameter [15:0] LOGICAL_MAP = 16'h0000;

  wire in_16 = LOGICAL_MAP[a * 2 +: 2];
  wire in_25 = LOGICAL_MAP[b * 2 +: 2];
  wire in_6  = LOGICAL_MAP[c * 2 +: 2];
  wire in_11 = LOGICAL_MAP[d * 2 +: 2];

  wire [15:0] sum = in_16 + in_25 + in_6 + in_11;
  assign out = sum[15];

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output out
);
  wire internal_wire;

  // Internal wire controlled by d
  assign internal_wire = d ? (a & b) : (a | b);

  // Output determined by c
  assign out = c ? internal_wire : (a ^ b);

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output reg out
);

  reg [2:0] state, next_state;

  parameter INIT  = 3'd0,
             WAIT1 = 3'd1,
             WAIT2 = 3'd2,
             WAIT3 = 3'd3,
             DONE  = 3'd4;

  always @(posedge d) begin
    if (c)
      state <= INIT;
    else
      state <= next_state;
  end

  always @(*) begin
    case (state)
      INIT:  next_state = a ? WAIT1 : INIT;
      WAIT1: next_state = b ? WAIT2 : WAIT1;
      WAIT2: next_state = a ? WAIT3 : WAIT2;
      WAIT3: next_state = b ? DONE : WAIT3;
      DONE:  next_state = DONE;
      default: next_state = INIT;
    endcase
  end

  always @(*) begin
    out = (state == DONE);
  end

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output reg out
);

  reg [1:0] s1, s2;
  reg [1:0] c1, c2;
  reg [2:0] counter;
  reg [1:0] x1, x2;
  reg [1:0] y1, y2;
  wire [1:0] x1_final, y1_final, x2_final, y2_final;
  wire [1:0] x_dir1, y_dir1, x_dir2, y_dir2;
  reg x_update1, x_update2, x_done1, x_done2;
  reg y_update1, y_update2, y_done1, y_done2;
  reg done1, done2;
  wire done;

  // Determine final coordinates
  assign x1_final = (x1 < x2_final) ? x1 : x2_final;
  assign y1_final = (y1 < y2_final) ? y1 : y2_final;
  assign x2_final = (x2 < x1_final) ? x2 : x1_final;
  assign y2_final = (y2 < y1_final) ? y2 : y1_final;

  // Calculate direction and distance for s1
  assign x_dir1 = (s1[0] ^ x1[0]) ? (s1[1] ? 1'b0 : 1'b1) : (x1[1] ? 1'b1 : 1'b0);
  assign y_dir1 = (s1[1] ^ y1[1]) ? (s1[0] ? 1'b0 : 1'b1) : (y1[0] ? 1'b1 : 1'b0);
  assign x_update1 = (abs(x1[1:0] - s1[1:0]) > 1);
  assign y_update1 = (abs(y1[1:0] - s1[1:0]) > 1);
  reg x_done1, y_done1;
  always @(*) x_done1 = (x1[1:0] == s1[1:0]);
  always @(*) y_done1 = (y1[1:0] == s1[1:0]);
  assign done1 = x_done1 & y_done1;

  // Calculate direction and distance for s2
  assign x_dir2 = (s2[0] ^ x2[0]) ? (s2[1] ? 1'b0 : 1'b1) : (x2[1] ? 1'b1 : 1'b0);
  assign y_dir2 = (s2[1] ^ y2[1]) ? (s2[0] ? 1'b0 : 1'b1) : (y2[0] ? 1'b1 : 1'b0);
  assign x_update2 = (abs(x2[1:0] - s2[1:0]) > 1);
  assign y_update2 = (abs(y2[1:0] - s2[1:0]) > 1);
  reg x_done2, y_done2;
  always @(*) x_done2 = (x2[1:0] == s2[1:0]);
  always @(*) y_done2 = (y2[1:0] == s2[1:0]);
  assign done2 = x_done2 & y_done2;

  // Done signal
  assign done = done1 & done2;

  // Update coordinates for s1
  always @(posedge a) begin
    if (b) begin
      x1 <= 2'b00;
      y1 <= 2'b00;
      s1 <= 2'b00;
    end else begin
      if (c && d) begin
        if (counter == 0) begin
          if (x_update1) x1 <= {x_dir1, x1[1:0] - 1'b1};
          if (y_update1) y1 <= {y_dir1, y1[1:0] - 1'b1};
          counter <= counter + 1;
        end
      end else if (counter > 0 && x_done1 || y_done1) begin
        s1 <= {x1[1:0], y1[1:0]};
        x1 <= 2'b00;
        y1 <= 2'b00;
        counter <= 0;
      end
    end
  end

  // Update coordinates for s2
  always @(posedge a) begin
    if (b) begin
      x2 <= 2'b00;
      y2 <= 2'b00;
      s2 <= 2'b00;
    end else begin
      if (c && d) begin
        if (counter == 0) begin
          if (x_update2) x2 <= {x_dir2, x2[1:0] - 1'b1};
          if (y_update2) y2 <= {y_dir2, y2[1:0] - 1'b1};
          counter <= counter + 1;
        end
      end else if (counter > 0 && x_done2 || y_done2) begin
        s2 <= {x2[1:0], y2[1:0]};
        x2 <= 2'b00;
        y2 <= 2'b00;
        counter <= 0;
      end
    end
  end

  // Update c1 and c2
  always @(posedge a) begin
    if (b) begin
      c1 <= 2'b00;
      c2 <= 2'b00;
    end else begin
      if (c) begin
        if (done1) c1 <= {x1_final, y1_final};
        if (done2) c2 <= {x2_final, y2_final};
      end
    end
  end

  // Update output
  always @(posedge a) begin
    if (b) begin
      out <= 1'b0;
    end else begin
      if (c && d) begin
        out <= (counter == 0) ? 1'b0 : 1'b1;
      end else if (done) begin
        out <= (c1 > c2) ? 1'b0 : 1'b1;
      end
    end
  end

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output reg out
);

  reg [2:0] s1, s2;
  reg [3:0] c1, c2;
  reg [2:0] i = 3'b0, j = 3'b0;

  // Shift registers s1 and s2 update on a or b
  always @(posedge a or posedge b) begin
    if (b) begin
      s1 <= 3'b0;
      s2 <= 3'b0;
    end else begin
      s1 <= {s1[1:0], d};
      s2 <= {s2[1:0], d};
    end
  end

  // Carry registers c1 and c2 update on a, b, or c
  always @(posedge a or posedge b) begin
    if (b) begin
      c1 <= 4'b0;
      c2 <= 4'b0;
    end else if (~c) begin
      c1 <= {c1[2:0], 1'b0};
      c2 <= {c2[2:0], 1'b0};
    end else begin
      c1 <= {c1[2:0], s1[2] ^ c1[3]};
      c2 <= {c2[2:0], s2[2] ^ c2[3]};
    end
  end

  // Counter i increments on a (when c=1) or b
  always @(posedge a or posedge b) begin
    if (b) begin
      i <= 3'b0;
    end else if (c) begin
      i <= i + 1;
    end
  end

  // Counter j increments on a (when c=0) or b
  always @(posedge a or posedge b) begin
    if (b) begin
      j <= 3'b0;
    end else if (~c) begin
      j <= j + 1;
    end
  end

  // Multiplexer mux selects c1 or c2 based on i/j
  wire [3:0] selected = (i < 3'd4) ? c1 : c2;

  // Output the selected carry bit
  always @(*) begin
    out = selected[0];
  end

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output reg out
);

  always @(b) begin
    if (c)
      out <= 1'b0;
    else if (d)
      out <= a;
    else
      out <= out;
  end

  always @(a) begin
    if (&({b, c}))
      out <= #100 1'b1;
  end

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output reg out
);

  reg [1:0] s1, s2;

  // First stage flip-flops
  always @(posedge a) begin
    if (b) begin
      s1 <= 2'b00;
    end else begin
      if (d)
        s1 <= {c, 1'b0};
      else
        s1 <= {s1[0], 1'b0};
    end
  end

  // Second stage flip-flops
  always @(posedge a) begin
    if (b) begin
      s2 <= 2'b00;
    end else begin
      if (d)
        s2 <= {s1[1], 1'b0};
      else
        s2 <= {s1[0], s1[0]};
    end
  end

  // Output logic
  always @(*) begin
    out = s2[1];
  end

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output reg out
);

  reg [1:0] s;
  reg [1:0] state;

  localparam IDLE = 2'b00;
  localparam STR    = 2'b01;
  localparam SHIFT  = 2'b10;

  always @(posedge a) begin
    case (state)
      IDLE: begin
        if (d) begin
          state <= STR;
          s <= 2'b00;
        end else begin
          state <= IDLE;
          s <= 2'b00;
        end
      end
      STR: begin
        if (d) begin
          s <= 2'b00;
          state <= STR;
        end else begin
          s <= {b, c};
          state <= SHIFT;
        end
      end
      SHIFT: begin
        if (d) begin
          s <= 2'b00;
          state <= STR;
        end else begin
          state <= SHIFT;
        end
      end
      default: state <= IDLE;
    endcase
  end

  always @* begin
    case (s)
      2'b01: out = 1'b1;
      2'b10: out = 1'b0;
      default: out = 1'b0;
    endcase
  end

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output reg out
);

  reg [1:0] s1, s2;
  reg [3:0] cnt;
  reg [7:0] cap1, cap2;

  // Combinational logic for capture and shift
  always @(posedge b) begin
    if (c) begin
      // Capture mode: sample input on a edges
      if (a) begin
        cap1 <= {cap1[6:0], d};
      end else begin
        cap2 <= {cap2[6:0], d};
      end
    end else begin
      // Shift mode: shift stored bits on a edges
      if (a) begin
        s1 <= {s1[0], d};  // Shift left, insert new bit at LSB
      end else begin
        s2 <= {s2[0], d};
      end
    end
  end

  // Parity check and output generation
  always @(posedge b) begin
    if (c) begin
      // In capture mode, reset counters and ready signal
      cnt <= 0;
      out <= 0;
    end else begin
      // In shift mode, update counters and ready signal
      cnt <= cnt + 1;
      out <= (s1[1] == s2[1]);  // Parity check using MSBs of s1 and s2
    end
  end

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output reg out
);

  reg [2:0] shift_reg;

  always @(posedge b) begin
    if (c) begin
      shift_reg <= 3'b000;
      out <= 1'b0;
    end else begin
      // Default shift operation
      shift_reg <= {shift_reg[1:0], a};
      out <= ({shift_reg[1:0], a} == {shift_reg[1:0], d});
    end
  end

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output reg out
);

  reg [1:0] s1, s2;
  reg [3:0] count;

  parameter s0 = 2'b00,
            s1_0 = 2'b01,
            s1_1 = 2'b10,
            s2_00 = 2'b11;

  always @(posedge d) begin
    if (c) begin
      s1 <= s0;
      s2 <= s0;
      count <= 4'b0;
    end else begin
      // Update s1
      if (count[0]) begin
        if (a) begin
          s1 <= s1_1;
          s2 <= s2;
        end else begin
          s1 <= s1_0;
          s2 <= s2;
        end
        count <= count << 1;
      end else begin
        s1 <= s1_0;
        s2 <= s2_00;
        count <= 4'b0;
      end

      // Update s2
      if (count[3]) begin
        if (b) begin
          s2 <= s1_1;
          s1 <= s1_0;
        end else begin
          s2 <= s2_00;
          s1 <= s1_0;
        end
        count <= count << 1;
      end else begin
        s2 <= s2_00;
        s1 <= s1_0;
        count <= 4'b0;
      end
    end
  end

  always @(*) begin
    out = (s2 == s1_0) ? 1'b1 : 1'b0;
  end

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);

  wire enable;
  assign enable = bump_right & bump_left;

  reg [31:0] regr;
  wire [31:0] next_regr = regr << 1;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      regr <= 32'b0;
    end else if (enable) begin
      regr <= next_regr;
    end
  end

  assign walk_left = next_regr[31];
  assign walk_right = regr[31];

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);

  // Synchronization registers for metastability prevention
  reg [1:0] sel_sync;
  reg [1:0] we_sync;

  // Select logic: 4-bit selector with hierarchical priority
  reg [3:0] sel;
  wire selected_clk;

  // Synchronization flip-flops for each clock domain
  reg [1:0] sel0_sync, sel1_sync, sel2_sync, sel3_sync;

  // Enable control for each clock
  wire we0, we1, we2, we3;

  // Synchronization process for select signal
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      sel_sync <= 2'b00;
    end else begin
      sel_sync <= {sel_sync[0], bump_left};
    end
  end

  // Synchronization process for enable signal
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      we_sync <= 2'b00;
    end else begin
      we_sync <= {we_sync[0], bump_right};
    end
  end

  // 4-bit selector with priority (sel[0] has highest priority)
  always @(*) begin
    if (sel_sync[1])       sel = 4'b0001;
    else if (sel_sync[0])  sel = 4'b0010;
    else if (bump_right)         sel = 4'b0100;
    else if (bump_left)         sel = 4'b1000;
    else                   sel = 4'b0000;
  end

  assign selected_clk = sel[0] ? clk :
                       sel[1] ? areset :
                       sel[2] ? bump_left :
                       bump_right;

  // Enable generation with clock gating
  assign we0 = sel[0] & bump_right;
  assign we1 = sel[1] & bump_right;
  assign we2 = sel[2] & bump_right;
  assign we3 = sel[3] & bump_right;

  // Synchronization flip-flops for each domain
  always @(posedge clk or posedge areset) begin
    if (areset) sel0_sync <= 2'b00;
    else       sel0_sync <= {sel0_sync[0], we0};
  end

  always @(posedge areset or posedge bump_left) begin
    if (bump_left) sel1_sync <= 2'b00;
    else       sel1_sync <= {sel1_sync[0], we1};
  end

  always @(posedge bump_left or posedge bump_right) begin
    if (bump_right) sel2_sync <= 2'b00;
    else       sel2_sync <= {sel2_sync[0], we2};
  end

  always @(posedge bump_right or posedge walk_left) begin
    if (walk_left) sel3_sync <= 2'b00;
    else       sel3_sync <= {sel3_sync[0], we3};
  end

  // Output assignment with reset
  assign walk_left = (areset) ? 1'b0 : sel3_sync[1];
  assign walk_right = walk_left;

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);

  reg [1:0] sck_sync;
  reg [1:0] cs_sync;
  reg prev_sck;
  wire cs_sync_any = cs_sync[1] | cs_sync[0];

  // SCK synchronization and edge detection
  always @(posedge clk or posedge bump_left) begin
    if (bump_left) begin
      sck_sync <= 2'b00;
      prev_sck <= 1'b0;
    end else begin
      sck_sync <= {sck_sync[0], bump_right};
      prev_sck <= sck_sync[1];
    end
  end

  wire sck_rising = (sck_sync[1] && !prev_sck);

  // CS synchronization and edge detection
  always @(posedge clk or posedge bump_left) begin
    if (bump_left) begin
      cs_sync <= 2'b00;
    end else begin
      cs_sync <= {cs_sync[0], areset};
    end
  end

  // Shift clock generation
  reg shift_clk;
  always @(posedge clk or posedge bump_left) begin
    if (bump_left) begin
      shift_clk <= 1'b0;
    end else if (cs_sync_any) begin
      shift_clk <= ~shift_clk;
    end else begin
      shift_clk <= 1'b0;
    end
  end

  assign walk_left = shift_clk;
  assign walk_right = cs_sync[1];

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);
  reg a_reg, b_reg;

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      a_reg <= 1'b0;
      b_reg <= 1'b0;
    end else begin
      if (bump_left)
        b_reg <= bump_right;
      else
        a_reg <= bump_right;
    end
  end

  assign walk_left = a_reg & b_reg;
  assign walk_right = a_reg | b_reg;

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
