  reg [7:0] decoder_out;
  always @(*) begin
    if (ground) begin
      if (bump_right)
        decoder_out = 8'b00000001 << clk;
      else
        decoder_out = 8'b00000001 << (clk + 1);
    end else
      decoder_out = 8'b00000000;
  end

  assign walk_left = decoder_out[0];
  assign walk_right = decoder_out[1];
  assign aaah = decoder_out[2];

