module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

`ifdef ACTIVE_HIGH
  localparam RESET = 1'b1;
  localparam WAIT  = 1'b2;
  localparam START = 1'b3;
  localparam LOAD  = 1'b4;
  localparam SHIFT = 1'b5;
  localparam COUNT = 1'b6;
  localparam END   = 1'b7;

  reg [2:0] current_state, next_state;

  always @(posedge clk or posedge reset) begin
    if (reset) current_state <= RESET;
    else current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      RESET: next_state = WAIT;
      WAIT:  next_state = data ? WAIT : START;
      START: next_state = LOAD;
      LOAD:  next_state = SHIFT;
      SHIFT: next_state = COUNT;
      COUNT: next_state = END;
      END:   next_state = WAIT;
      default: next_state = RESET;
    endcase
  end

  assign start_shifting = (current_state == LOAD) || (current_state == COUNT);

`else
  localparam IDLE = 1'b0;
  localparam READ = 1'b1;
  localparam WRIT = 1'b2;
  localparam DONE = 1'b3;

  reg current_state, next_state;

  always @(posedge clk or posedge reset) begin
    if (reset) current_state <= IDLE;
    else current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      IDLE: next_state = data ? READ : IDLE;
      READ: next_state = WRIT;
      WRIT: next_state = DONE;
      DONE: next_state = IDLE;
      default: next_state = IDLE;
    endcase
  end

  assign start_shifting = (current_state == READ) || (current_state == WRIT);
`endif

endmodule

