module TopModule (
  input clock,
  input a,
  output reg p,
  output reg q
);

  localparam IDLE = 2'b00;
  localparam START = 2'b01;
  localparam DATA = 2'b10;
  localparam STOP = 2'b11;

  reg [1:0] current_state, next_state;
  reg [2:0] counter;
  localparam MAX_COUNT = 255;

  always @(posedge clock) begin
    if (a) begin
      current_state <= IDLE;
      counter <= MAX_COUNT;
      p <= 0;
      q <= 0;
    end else begin
      current_state <= next_state;
      if (current_state == START)
        counter <= MAX_COUNT;
      else if (current_state == DATA)
        counter <= counter - 1;
      else
        counter <= MAX_COUNT;
    end
  end

  always @(*) begin
    case (current_state)
      IDLE:    next_state = (counter == 0) ? START : IDLE;
      START:   next_state = (counter == 0) ? DATA : START;
      DATA:    next_state = (counter == 0) ? STOP : DATA;
      STOP:    next_state = (counter == 0) ? IDLE : STOP;
      default: next_state = IDLE;
    endcase
  end

  always @(*) begin
    case (current_state)
      IDLE: begin
        p = 0;
        q = 0;
      end
      START: begin
        p = 1;
        q = 1;
      end
      DATA: begin
        p = 1;
        q = (counter < 2) ? 0 : 1;
      end
      STOP: begin
        p = 1;
        q = 0;
      end
      default: begin
        p = 0;
        q = 0;
      end
    endcase
  end

endmodule

module TopModule (
  input clock,
  input a,
  output reg p,
  output reg q
