  reg [1:0] state, next_state;
  reg [2:0] counter;

  parameter IDLE = 2'b00;
  parameter START = 2'b01;
  parameter WAIT = 2'b10;

  // State register
  always @(posedge clock) begin
    if (a)
      state <= IDLE;
    else
      state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      IDLE: next_state = (~a) ? START : IDLE;
      START: next_state = WAIT;
      WAIT: next_state = (counter == 3'd4) ? IDLE : WAIT;
      default: next_state = IDLE;
    endcase
  end

  // Counter logic
  always @(posedge clock) begin
    if (a)
      counter <= 3'b0;
    else
      if (state == WAIT)
        counter <= counter + 1;
      else
        counter <= 3'b0;
  end

  // Output logic
  always @(*) begin
    case (state)
      IDLE: {p, q} = 2'b11;
      START: {p, q} = 2'b00;
      WAIT: {p, q} = 2'b11;
      default: {p, q} = 2'b11;
    endcase
  end

endmodule

