  always @(*) begin
    case (state)
      IDLE: next_state = (req0 || req1) ? IDLE : GNT0;
      GNT0: next_state = req0 ? GNT0 : IDLE;
      GNT1: next_state = req1 ? GNT1 : IDLE;
