localparam IDLE = 2'b00;
localparam MOVING_UP = 2'b01;
localparam MOVING_DOWN = 2'b10;

reg [1:0] state = IDLE;

// Previous button states for edge detection
reg p_C1, p_C2, p_C3;

// Edge detection registers update on clk
always @(posedge clk) begin
    p_C1 <= rst_n;
    p_C2 <= a;
    p_C3 <= rise;
end

// State transitions and output logic
always @(posedge clk) begin
    case (state)
        IDLE: begin
            if (!p_C1 && rst_n)          // C1 pressed (active low)
                state <= MOVING_UP;
            else if (!p_C2 && a)     // C2 pressed
                state <= MOVING_DOWN;
            else
                state <= IDLE;
        end
        MOVING_UP: begin
            if (!p_C2 && a)          // C2 pressed
                state <= IDLE;
            else
                state <= MOVING_UP;
        end
        MOVING_DOWN: begin
            if (!p_C1 && rst_n)          // C1 pressed
                state <= IDLE;
            else
                state <= MOVING_DOWN;
        end
        default: state <= IDLE;
    endcase
end

// LED output logic (combinational)
always @(*) begin
    rise = (state == MOVING_UP);
    down = (state == MOVING_DOWN);
end

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

localparam IDLE = 2'b00;
localparam ARMED = 2'b01;
localparam CAPTURING = 2'b10;

reg [1:0] state, next_state;
reg [31:0] counter;
reg [31:0] sample_buffer [0:255];
reg [7:0] sample_count;
reg [2:0] bit_count;
wire ramp_edge = (rst_n & ~a) | (~rst_n & a);

always @(posedge clk) begin
	if (a) begin
		state <= IDLE;
		counter <= 0;
		sample_buffer[0] <= 0;
		sample_count <= 0;
		bit_count <= 0;
		rise <= 0;
		down <= 0;
		next_state <= IDLE;
	end else begin
		rise <= 0;
		down <= 0;
		case (state)
			IDLE: begin
				next_state <= ARMED;
				counter <= 0;
				sample_buffer[0] <= 0;
				sample_count <= 0;
				bit_count <= 0;
			end
			ARMED: begin
				if (ramp_edge) begin
					sample_buffer[0] <= counter;
					sample_count <= 0;
					bit_count <= 0;
					state <= CAPTURING;
			 end
			end
			CAPTURING: begin
				if (ramp_edge) begin
					sample_buffer[0] <= counter;
					sample_count <= sample_count + 1;
					if (sample_count < 255)
						bit_count <= bit_count + 1;
			 end
				if (sample_count == 255 && bit_count == 8) begin
					down <= 1;
					rise <= sample_buffer[0][7:0];
					state <= IDLE;
			 end else begin
					bit_count <= bit_count + 1;
			 end
			end
			default: state <= IDLE;
		endcase
	}
end

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

parameter ACTIVE_LOW = 1;  // Configurable active-low (default) or active-high

// State definitions
localparam [1:0] IDLE     = 2'b00,
                 LEFT     = 2'b01,
                 RIGHT    = 2'b10,
                 ACTIVE_LOW = 2'b11;

reg [1:0] current_state, next_state;

// State register with synchronous reset
always @(posedge rst_n or negedge clk) begin
    if (!clk)
        current_state <= IDLE;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    next_state = current_state; // Default: stay in current state
    if (a) begin
        case (current_state)
            IDLE:       next_state = ACTIVE_LOW;
            ACTIVE_LOW: next_state = clk ? LEFT : RIGHT;
            LEFT:       next_state = ACTIVE_LOW;
            RIGHT:      next_state = ACTIVE_LOW;
            default:    next_state = IDLE;
        endcase
    end
end

// Output logic with synchronous reset
always @(posedge rst_n or negedge clk) begin
    if (!clk) begin
        rise <= 1'b0;
        down <= 1'b0;
    end else begin
        case (next_state)
            IDLE:       {rise, down} <= 2'b00;
            LEFT:       {rise, down} <= {1'b1, 1'b0};
            RIGHT:      {rise, down} <= {1'b0, 1'b1};
            ACTIVE_LOW: {rise, down} <= {1'b1, 1'b1};
            default:    {rise, down} <= 2'b00;
        endcase
    end
end

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg [1:0] state_counter;
reg [1:0] delay_counter;

localparam IDLE = 2'd0;
localparam DELAY = 2'd1;
localparam COUNT = 2'd2;
localparam DONE = 2'd3;

always @(posedge clk) begin
	if (rst_n) begin
		state_counter <= IDLE;
		delay_counter <= 2'b0;
		rise <= 1'b0;
		down <= 1'b0;
		end
	else begin
		case (state_counter)
			IDLE: begin
				if (a) begin
					state_counter <= DELAY;
					delay_counter <= 2'b0;
				end
				rise <= 1'b0;
				down <= 1'b0;
			end
			DELAY: begin
				delay_counter <= delay_counter + 1'b1;
				rise <= 1'b0;
				down <= 1'b0;
				if (delay_counter == 2'b1) begin
					state_counter <= COUNT;
				end
			end
			COUNT: begin
				delay_counter <= delay_counter + 1'b1;
				rise <= 1'b0;
				down <= 1'b0;
				if (delay_counter == 2'b1) begin
					state_counter <= DONE;
				end
			end
			DONE: begin
				rise <= 1'b1;
				down <= 1'b1;
				state_counter <= IDLE;
			end
			default: begin
				state_counter <= IDLE;
				rise <= 1'b0;
				down <= 1'b0;
			end
		endcase
		end
end

endmodule

