module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

    // Synchronous clk_b and reset handling
    always @(posedge clk_a) begin
        if (clk_b) begin
            dataout <= 4'b0;
        end else if (arstn) begin
            dataout <= 4'b0;
        end else if (brstn) begin
            dataout <= data_in;
        end
    end

    // Post-release logic for data_en
    always @(negedge clk_a) begin
        if (clk_b || arstn) begin
            dataout <= 4'b0;
        end else if (!brstn && data_en) begin
            dataout <= data_in;
        end
    end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

always @(posedge clk_a) begin
	if (clk_b) begin
		dataout <= 4'b0;
	end else if (arstn) begin
		dataout <= 4'b0;
	end else if (brstn) begin
		dataout <= data_in;
	end else if (data_en) begin
		dataout <= dataout;
	end else begin
		dataout <= 4'b0;
	end
end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

    // Synchronize brstn and data_en to system clock
    reg [1:0] rst_meta, rst_sync;
    reg [1:0] done_meta, done_sync;

    // Delay elements for brstn and data_en
    reg delay_rst, delay_done;

    // State machine parameters
    localparam IDLE      = 2'b00;
    localparam ALIGN     = 2'b01;
    localparam SHIFT     = 2'b10;
    localparam COMPLETE  = 2'b11;

    reg [1:0] current_state, next_state;

    // Synchronization and delay logic
    always @(posedge clk_a) begin
        if (clk_b) begin
            rst_meta <= 2'b00;
            rst_sync <= 2'b00;
            delay_rst <= 1'b0;
        end else begin
            rst_meta <= {rst_meta[0], brstn};
            rst_sync <= rst_meta[1];
            delay_rst <= rst_sync[1];
        end

        if (clk_b) begin
            done_meta <= 2'b00;
            done_sync <= 2'b00;
            delay_done <= 1'b0;
        end else begin
            done_meta <= {done_meta[0], data_en};
            done_sync <= done_meta[1];
            delay_done <= done_sync[1];
        end
    end

    // State transition
    always @(posedge clk_a) begin
        if (clk_b) current_state <= IDLE;
        else current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                next_state = (delay_rst) ? ALIGN : IDLE;
            end
            ALIGN: begin
                if (delay_rst) next_state = SHIFT;
                else next_state = ALIGN;
            end
            SHIFT: begin
                if (delay_rst) next_state = COMPLETE;
                else next_state = SHIFT;
            end
            COMPLETE: begin
                next_state = (delay_done) ? IDLE : COMPLETE;
            end
            default: next_state = IDLE;
        endcase
    end

    // Output logic
    always @(posedge clk_a) begin
        if (clk_b) dataout <= 4'b0;
        else if (current_state == ALIGN) dataout <= data_in;
    end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [1:0] s_reg;
reg [1:0] next_s;

// State register update
always @(posedge IN or posedge RST) begin
    if (RST)
        s_reg <= 2'b00;
    else
        s_reg <= next_s;
end

// Next state logic
always @(*) begin
    if (RST)
        next_s = 2'b00;
    else begin
        case ({s_reg, CLK})
            4'b0000: next_s = 2'b00; // S0 with B0
            4'b0001: next_s = 2'b01; // S0 with B1
            4'b0010: next_s = 2'b00; // S1 with B0
            4'b0011: next_s = 2'b01; // S1 with B1
            4'b0100: next_s = 2'b10; // S2 with B0
            4'b0101: next_s = 2'b11; // S2 with B1
            4'b0110: next_s = 2'b10; // S3 with B0
            4'b0111: next_s = 2'b11; // S3 with B1
            4'b1000: next_s = 2'b00; // S4 with B0
            4'b1001: next_s = 2'b01; // S4 with B1
            4'b1010: next_s = 2'b00; // S5 with B0
            4'b1011: next_s = 2'b01; // S5 with B1
            4'b1100: next_s = 2'b00; // S6 with B0
            4'b1101: next_s = 2'b01; // S6 with B1
            4'b1110: next_s = 2'b00; // S7 with B0
            4'b1111: next_s = 2'b01; // S7 with B1
            default: next_s = 2'b00;
        endcase
    end
end

// Output logic
always @(*) begin
    case (next_s)
        2'b00: MATCH = 1;
        2'b01: MATCH = 0;
        default: MATCH = 1;
    endcase
end

endmodule

