module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [4:0] sim_time; // Simulate up to 32 cycles (0-31)

always @(posedge IN or posedge CLK) begin
    if (CLK) begin
        MATCH <= 0;
        sim_time <= 0;
    end else begin
        if (sim_time < 32) begin
            if (RST[sim_time]) 
                MATCH <= 1;
            else 
                MATCH <= 0;
            sim_time <= sim_time + 1;
        end
    end
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [16:0] shift_reg;
reg [4:0] counter;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        shift_reg <= 17'b0;
        counter <= 5'b0;
        MATCH <= 1'b0;
    end else begin
        if (counter < 17) begin
            shift_reg[counter] <= IN;
            counter <= counter + 1;
            MATCH <= 1'b0;
        end else begin
            MATCH <= shift_reg[16];
            counter <= counter + 1;
        end
    end
end

endmodule

