module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

parameter INIT = 2'b00;
parameter S0 = 2'b01;
parameter S1 = 2'b10;
parameter S2 = 2'b11;

reg [1:0] current_state, next_state;

// State register with synchronous reset
always @(posedge CLK or posedge RST) begin
    if (RST) current_state <= INIT;
    else current_state <= next_state;
end

// Next state logic based on current state and input
always @(*) begin
    case (current_state)
        INIT: next_state = IN ? S1 : S0; // Example transition
        S0: next_state = IN ? S1 : S0;   // Example transition
        S1: next_state = IN ? S2 : S0;   // Example transition
        S2: next_state = IN ? S2 : S0;   // Example transition
        default: next_state = INIT;
    endcase
end

// Output logic based on current state and input
always @(*) begin
    if (current_state == S0)
        MATCH = IN; // Example output condition
    else
        MATCH = 1'b0;
end

endmodule

