    reg [15:0] lut [0:15];
    integer i;

    always @(posedge clk) begin
        if (rst_n) begin
            for (i = 0; i < 16; i = i + 1)
                lut[i] <= lut_mask;
        end
    end

    assign valid_out = lut[d]['b];
    assign dout = lut[d]['v];

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [3:0] Q;
wire [3:0] J, K;

// J and K calculations
assign J[0] = d[1] | (d[3] & d[2]);
assign J[1] = d[2] | (d[3] & d[1]);
assign J[2] = d[3] | (d[1] & d[0]);
assign J[3] = d[0] | (d[1] & d[2]);

assign K[0] = d[1] | (d[3] & d[2]);
assign K[1] = d[2] | (d[3] & d[1]);
assign K[2] = d[3] | (d[1] & d[0]);
assign K[3] = d[0] | (d[1] & d[2]);

// Q register with synchronous rst_n
always @(posedge clk) begin
    if (rst_n)
        Q <= 4'b0000;
    else
        Q <= {Q[2:0], 1'b0} & {K, J}; // K and J concatenated as 8-bit input
end

assign valid_out = Q[3];
assign dout = Q[0];

endmodule

