module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
`ifdef TDT_GATED_CELL
     // Gated cell with differential outputs
     wire x1, x2;
     assign x1 = (clk & rst_n) ? ~data_in : 1'b0;
     assign x2 = (clk & rst_n) ?  data_in : 1'b0;
     assign sequence_detected = x1;
`else
`ifdef TDT_FABRIC_CELL
     // Fabric cell with bundled outputs
     wire y1, y2, y3, y4;
     assign y1 = clk & rst_n;
     assign y2 = clk & ~rst_n;
     assign y3 = ~clk & rst_n;
     assign y4 = ~clk & ~rst_n;
     assign sequence_detected = y1;
`else
`ifdef TDT_STANDARD_CELL
     // Standard cell with output inverter
     assign sequence_detected = ~(clk & rst_n & data_in);
`endif
`endif
`endif
endmodule

